        'intros' => [
            'custom_fields' => 'Crie os detalhes extras de que um tipo de ticket precisa - uma data de início e um nome de usuário em um novo funcionário, por exemplo - e escolha em quais tipos de ticket cada um aparece. Cada campo decide por si se deve ser preenchido quando um ticket é registrado, quando é fechado ou nos dois casos, e se o solicitante é questionado sobre ele no portal.',
            'checklists' => 'Uma lista de verificação pode marcar etapas como obrigatórias. Isto decide o que acontece se alguém fechar um ticket antes que essas etapas sejam marcadas.',
            'mandatory_fields' => 'Escolha quais campos do ticket devem ser preenchidos antes que um ticket seja fechado, e o que acontece quando alguém fecha um com algum deles vazio. A regra se aplica em todo lugar onde um ticket pode ser fechado: a tela do ticket, ações em massa, a API REST e os fluxos de trabalho.',
            'departments' => 'Os departamentos agrupam e encaminham os tickets para a área certa da sua organização — crie os que sua central de serviços usa para categorizar e atribuir o trabalho.',
            'teams' => 'As equipes determinam quais departamentos os analistas podem acessar. Atribua departamentos às equipes e, em seguida, atribua analistas às equipes para controlar o acesso deles.',
            'ticket_types' => 'Os tipos de ticket classificam o que é uma solicitação (ex. Incidente, Solicitação de Serviço) — defina os tipos que os analistas podem definir em um ticket.',
            'ticket_origins' => 'As origens de ticket registram como um ticket chegou (ex. E-mail, Telefone, Portal) — defina as origens que os analistas podem escolher.',
            'mailboxes' => 'As caixas postais conectam o FreeITSM a contas de e-mail para que as mensagens recebidas se tornem tickets e as respostas sejam enviadas de volta — adicione e autentique as que sua central de serviços monitora.',
            'privacy' => 'Um ticket não contém apenas a sua conversa com quem o abriu. Encaminhar para um fornecedor, ou copiar um colega, coloca essa mensagem no mesmo ticket — e a resposta dessa pessoa também vai parar lá. Isto define quanto disso o solicitante vê no portal de autoatendimento.',
            'indexing' => 'O texto dentro dos anexos é lido para que possa ser pesquisado. Arquivos do Word, Excel, PowerPoint e texto simples são lidos pelo próprio FreeITSM, assim que chegam. PDFs, arquivos antigos do Office e documentos digitalizados precisam de um serviço de leitura de documentos separado — configure-o em <strong>Sistema &rarr; Integrações &rarr; Apache Tika</strong> — e como esses demoram muito mais, são lidos em segundo plano. Estas duas opções decidem quando esse trabalho em segundo plano acontece.',
            'merge_behaviour' => 'Quando dois tickets são a mesma coisa, um analista pode mesclá-los. Estas configurações definem o que isso faz com as referências de ticket que seus solicitantes já têm, e o que acontece com as conversas. Valem para todos — uma mesclagem muda o que o cliente vê, então dois analistas na mesma caixa postal não podem discordar sobre isso.',
            'reply_templates' => 'Respostas prontas que seus analistas podem inserir em uma resposta em vez de redigitá-las. Estes são os modelos compartilhados que toda a equipe vê — os modelos particulares de cada analista são salvos na janela de resposta e não aparecem aqui.',
            'rota_shifts' => 'Os turnos são os modelos de padrão de trabalho (ex. Manhã, Tarde, Sobreaviso) atribuídos aos analistas na escala de equipe — defina-os aqui antes de montar a escala.',
            'analysts' => 'Os analistas são a equipe que faz login e trabalha nos tickets — adicione-os, redefina senhas e atribua-os a equipes para controlar o acesso deles.',
            'general' => 'As configurações gerais controlam como os tickets se comportam - reabertura, adiamento e por quanto tempo mensagens e conversas são exibidas.',
            'statuses' => 'Estados de fluxo de trabalho em que um ticket pode estar. Status marcados como <em>Fechado</em> contam como finais — usados por relatórios, contadores do watchtower e o carimbo de data/hora de fechamento definido automaticamente na atribuição. Exatamente um status é o padrão para novos tickets.',
            'priorities' => 'Faixas de prioridade exibidas nos tickets. Exatamente uma prioridade é a padrão para novos tickets.',
            'rota_locations' => 'Onde cada analista está trabalhando em um determinado dia — usado pela escala de equipe e exibido como um emblema colorido em cada entrada. Exatamente um local é o padrão para novas entradas de escala.',
            'email_templates' => 'Respostas de e-mail automatizadas acionadas por eventos de ticket. Apenas o primeiro modelo ativo por evento é usado.',
        ],
        'messaging' => [
            'channels_heading' => 'Canais de mensagens',
            'channels_intro' => 'Deixe os clientes conversarem com um analista pelo WhatsApp — cada mensagem se torna um ticket, assim como o e-mail. Adicione um canal abaixo e cole sua <strong>URL do webhook</strong> no seu provedor (Twilio ou Meta) para que as mensagens recebidas cheguem a esta instalação.',
            'base_url_label' => '<strong>URL base pública</strong>',
            'base_url_placeholder' => 'https://seu-dominio.com  (ou seu endereço ngrok durante os testes)',
            'base_url_help' => 'O endereço que os provedores usam para acessar esta instalação. Defina-o e os URLs de webhook abaixo ficam prontos para copiar e colar. Deixe em branco para usar o endereço de onde você está navegando. Testando localmente? Execute <code>ngrok http 80</code> e cole o endereço <code>https://…ngrok-free.dev</code> que ele exibe.',
            'templates_heading' => 'Modelos de mensagem',
            'templates_intro' => 'Modelos pré-aprovados permitem que um analista responda <strong>após o encerramento da janela de 24 horas</strong>. O WhatsApp só permite texto livre em até 24 horas após a última mensagem do cliente; fora disso, só pode ser enviado um modelo aprovado pela Meta/Twilio. Crie &amp; aprove o modelo no seu provedor e adicione sua definição aqui (com marcadores <code>{{1}}</code>, <code>{{2}}</code>) para que os analistas possam selecioná-lo e preenchê-lo.',
        ],
        'webchat' => [
