        'sla' => [
            'heading' => 'Acordos de nível de serviço',
            'intro' => 'SLAs cientes do horário comercial com metas de resposta e resolução por prioridade. O relógio pausa em status marcados como "Pausa o SLA" na <a href="#" onclick="event.preventDefault();switchTab(\'statuses\');">aba Status</a>. Veja as <a href="https://github.com/edmozley/freeitsm/blob/main/docs/sla.md" target="_blank">notas de design</a>.',
            'global_heading' => 'Configurações globais',
            'enforce_from' => 'Aplicar SLAs a partir de',
            'enforce_from_help' => 'Deixe em branco para <strong>desativar totalmente a aplicação de SLA</strong>. Defina uma data/hora e apenas os tickets criados nesse momento ou depois são avaliados &mdash; útil para isentar tickets existentes ao ativar SLAs pela primeira vez.',
            'priority_change_label' => 'Quando a prioridade de um ticket muda no meio do processo',
            'priority_change_forward' => 'Aplicar o novo SLA a partir do ponto de mudança em diante',
            'priority_change_recompute' => 'Recalcular retroativamente em relação à nova meta',
            'priority_change_reset' => 'Zerar completamente o relógio do SLA',
            'reopen_label' => 'Quando um ticket fechado é reaberto',
            'reopen_reset' => 'Iniciar o SLA do zero',
            'reopen_continue' => 'Continuar de onde o relógio pausou',
            'first_response_label' => 'A primeira resposta conta como',
            'first_response_outbound' => 'Apenas e-mail enviado (Responder / Encaminhar)',
            'first_response_status' => 'Mudança de status para fora do padrão',
            'first_response_either' => 'Qualquer um, o que ocorrer primeiro',
            'warning_threshold' => 'Limite de aviso (%)',
            'warning_threshold_help' => 'Os tickets são sinalizados visualmente na caixa de entrada nesta % do SLA decorrido.',
            'notifications_label' => 'Notificações',
            'notify_assignee' => 'Enviar e-mail ao responsável no limite de aviso',
            'notify_lead' => 'Enviar e-mail ao líder da equipe na violação',
            'save_global' => 'Salvar configurações globais',
            'targets_heading' => 'Metas de SLA por prioridade',
            'targets_intro' => 'Tempos de resposta e resolução para cada prioridade de ticket. Os tempos estão em minutos (60 = 1 hora, 240 = 4 horas, 1440 = 1 dia). O calendário determina contra quais horas comerciais o relógio conta. Deixe em branco para pular essa meta.',
            'col_priority' => 'Prioridade',
            'col_response_mins' => 'Resposta (min)',
            'col_resolution_mins' => 'Resolução (min)',
            'col_calendar' => 'Calendário',
            'col_save' => 'Salvar',
            'calendars_heading' => 'Calendários comerciais',
            'calendars_intro' => 'Defina horário de trabalho, fusos horários e listas de feriados. Os calendários são referenciados pelas metas de SLA (acima) e por prioridades individuais. Um calendário é o padrão para novas prioridades.',
            'col_name' => 'Nome',
            'col_timezone' => 'Fuso horário',
            'col_hours' => 'Horas',
            'col_holidays' => 'Feriados',
            'col_default' => 'Padrão',
            'default_badge' => 'Padrão',
            'no_active_priorities' => 'Nenhuma prioridade ativa - adicione algumas na aba Prioridades.',
            'no_calendars' => 'Nenhum calendário definido ainda. Adicione um acima.',
            'col_actions' => 'Ações',
            'notifs_heading' => 'Notificações de violação',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">Como funcionam as regras de notificação</strong>Cada regra tem quatro partes: um <strong>escopo</strong>, um <strong>disparador</strong>, um <strong>alvo</strong> e uma lista de <strong>destinatários</strong>.<br><br>O <strong>escopo</strong> pode ser <em>Padrão</em> (a regra se aplica a tickets de todos os departamentos) ou um <em>departamento específico</em> (a regra se aplica apenas a tickets desse departamento).<br>Quando um ticket está sendo avaliado, o sistema procura primeiro uma regra que corresponda ao seu departamento &mdash; se existir uma, essa regra prevalece e o padrão é ignorado. Se não houver uma regra específica do departamento, a regra padrão é usada. Assim você pode definir padrões sensatos que cobrem todos os departamentos e, em seguida, criar exceções onde uma equipe tem necessidades de escalonamento diferentes.<br><br>O <strong>disparador</strong> é <em>Aviso</em> (o ticket cruzou o limite de aviso &mdash; possível violação se aproximando) ou <em>Violação</em> (o ticket agora excedeu sua meta de SLA &mdash; violação real). Cada um é sua própria regra, então você pode notificar pessoas diferentes para avisos vs. violações.<br><br>O <strong>alvo</strong> é qual relógio de SLA observar &mdash; <em>Resposta</em>, <em>Resolução</em> ou <em>Ambos</em>.<br><br>Os <strong>destinatários</strong> podem ser qualquer combinação de: o responsável atual do ticket, todos os analistas das equipes do departamento do ticket, um analista nomeado e/ou uma lista de endereços de e-mail livres (útil para caixas de entrada compartilhadas ou pontes de e-mail do Slack/Teams).<br><br><strong style="color:var(--warning-text, #92400e);">Sem regras = sem e-mails.</strong> Mesmo que um ticket viole, nada é disparado até você adicionar pelo menos uma regra (comece com um par Aviso + Violação de escopo Padrão para obter cobertura para tudo).',
            'notifs_dedup' => 'Cada ticket dispara no máximo um e-mail por alvo por disparador &mdash; o worker cron rastreia o que já foi enviado para que você não receba duplicatas.',
            'col_scope' => 'Escopo',
            'col_trigger' => 'Disparador',
            'col_target' => 'Alvo',
            'col_recipients' => 'Destinatários',
            'col_active' => 'Ativo',
            'notifs_cron_note' => 'O worker cron que dispara esses e-mails fica em <code>cron/sla_breach_check.php</code>. Veja <code>docs/sla-cron-setup.md</code> para a configuração do Agendador de Tarefas do Windows + cron do Linux.',
            'cron_heading' => 'Atividade do cron',
            'cron_refresh' => 'Atualizar',
            'cron_intro' => 'Últimas <span id="slaCronRunsLimit">20</span> invocações do cron de verificação de violação (CLI e HTTP). Inclui solicitações rejeitadas (limitadas por taxa, com falha de autenticação) para que a mesma fonte de verdade dê suporte às verificações de limite de taxa e auditorias de segurança. Removidas automaticamente após <strong><span id="slaCronRetentionDays">30</span> dias</strong>; o intervalo mínimo entre execuções bem-sucedidas é de <strong><span id="slaCronMinInterval">30</span>s</strong> (ambos configuráveis em <code>system_settings</code>).',
            'col_when' => 'Quando',
            'col_source' => 'Origem',
            'col_duration' => 'Duração',
            'col_sent' => 'Enviados',
            'col_skipped' => 'Ignorados',
            'col_errors' => 'Erros',
            'col_outcome' => 'Resultado',
        ],
        'dept_confidential' => [
            'label' => 'Os tickets aqui são confidenciais',
            'help' => 'Todo ticket deste departamento, ou movido para ele, é marcado como Confidencial e, portanto, não é mostrado aos gestores do solicitante. Ativar isto também marca os tickets que já estão aqui. Desativar não altera nenhum ticket - torne-o Normal de novo no próprio ticket.',
            'chip' => 'Confidencial',
            'raised' => 'Tickets agora marcados como confidenciais: {count}.',
