        'mailbox_confidential' => [
            'label' => 'Os tickets desta caixa postal são confidenciais',
            'help' => 'Para uma caixa postal como a de RH. Todo ticket que chega aqui é marcado como Confidencial no instante em que chega, antes de alguém o ler, e portanto não é mostrado aos gestores do solicitante.',
        ],
        'pauses_sla' => [
            'label' => 'Pausa o relógio do SLA',
            'help' => 'Quando um ticket está neste status, o relógio do SLA para de contar. Usado para status em que o ticket não está sendo trabalhado ativamente (ex. <em>Em espera</em>, <em>Aguardando resposta</em>).',
        ],
        'rota_weekends' => 'Incluir fins de semana na escala',
        'numbering' => [
            'heading' => 'Numeração de tickets',
            'intro' => 'Todo ticket recebe uma referência. É o que as pessoas leem em voz alta no telefone, escrevem em um formulário e pesquisam seis meses depois, então vale a pena que seja algo que uma pessoa consiga falar. Você escolhe o formato aqui.',
            'style' => 'Como os números são gerados',
            'style_sequential' => 'Contando para cima',
            'style_sequential_help' => 'TICKET-000001, TICKET-000002, e assim por diante. Fácil de falar, fácil de reconhecer, e a ordem diz qual veio primeiro.',
            'style_random' => 'Aleatório',
            'style_random_help' => 'Três letras e oito dígitos, como CKQ-418-73926. É o que o FreeITSM sempre fez. Ninguém consegue adivinhar quantos tickets você tem, mas também ninguém consegue ler um em voz alta.',
            'format' => 'Qual é a aparência de um número',
            'format_help' => 'Coloque <code>{######}</code> onde os dígitos devem ficar &mdash; um sustenido por dígito. Qualquer outra coisa é mantida como você digitou. Você também pode usar <code>{YYYY}</code> ou <code>{YY}</code> para o ano, <code>{MM}</code> e <code>{DD}</code>, e <code>{TYPE}</code> ou <code>{COMPANY}</code> para um código curto tirado do tipo de ticket ou da empresa. Por exemplo <code>INC-{YYYY}-{#####}</code>.',
            'preview_label' => 'Os próximos ficariam assim',
            'start' => 'Começar a contar a partir de',
            'start_help' => 'Útil se você está migrando de outro sistema e quer continuar de onde parou.',
            'scope' => 'Contar separadamente para',
            'scope_global' => 'Uma sequência para tudo',
            'scope_per_type' => 'Cada tipo de ticket',
            'scope_per_company' => 'Cada empresa',
            'scope_help' => 'Contar por tipo de ticket dá a incidentes e solicitações suas próprias sequências de números, que é como a maioria das centrais de serviço grandes faz. Se você contar separadamente, o formato precisa indicar qual é qual — coloque {TYPE} ou {COMPANY} nele, ou cada grupo produziria os mesmos números.',
            'reset' => 'Recomeçar',
            'reset_never' => 'Nunca — continuar contando',
            'reset_yearly' => 'Todo ano',
            'reset_monthly' => 'Todo mês',
            'reset_help' => 'Só é útil se o ano ou mês fizer parte do número; caso contrário, você terá duplicatas. Combine com algo como <code>INC-{YYYY}-{#####}</code>.',
            'existing_note' => '<strong>Nada que já está numerado muda.</strong> Os tickets existentes mantêm a referência que têm, e toda referência que o FreeITSM já emitiu continua funcionando &mdash; inclusive em respostas a e-mails antigos. Se você também quiser renumerar os tickets existentes, há uma ferramenta para isso abaixo. <strong>Você não vai ficar sem dígitos:</strong> a largura que você escolhe é um mínimo, então o ticket 1.000.001 simplesmente ganha um dígito a mais em vez de quebrar.',
            'saved' => 'Numeração de tickets salva.',
            'renumber_heading' => 'Renumerar tickets existentes',
            'renumber_intro' => 'Reescreve a referência de cada ticket existente no esquema acima, dos mais antigos primeiro. Principalmente útil logo depois de migrar de outro sistema, quando você quer que tudo pareça consistente.',
            'renumber_safety' => '<strong>As referências antigas continuam funcionando.</strong> Todo número que um ticket já teve é lembrado, então uma resposta a um e-mail citando o antigo ainda cai no ticket certo &mdash; exatamente como acontece quando tickets são mesclados. Um número aposentado também nunca é dado a um ticket diferente. Isto não pode ser desfeito, porém, então veja a pré-visualização primeiro.',
            'renumber_preview' => 'Pré-visualização',
            'renumber_go' => 'Renumerar',
            'renumber_preview_first' => 'Pré-visualize primeiro — o botão é ativado assim que você vir o que ele faria.',
            'renumber_preview_heading' => 'Somente pré-visualização &mdash; nada foi alterado.',
            'renumber_done_heading' => 'Tickets renumerados.',
            'renumber_summary' => '{changing} de {total} ticket(s) seriam renumerados. {skipped} já correspondem.',
            'renumber_next_after' => 'O próximo ticket novo seria {number}.',
            'renumber_confirm_title' => 'Renumerar todos os tickets?',
            'renumber_confirm' => 'Isto reescreve a referência de cada ticket existente.

As referências antigas continuam funcionando, então respostas a e-mails antigos ainda encontram o ticket certo. Mas os números que as pessoas anotaram, colocaram em formulários e salvaram nas próprias planilhas não serão mais os mostrados no FreeITSM.

Isto não pode ser desfeito. Continuar?',
