        'general' => [
            'system_name' => 'Nome do sistema',
            'system_name_moved' => 'O nome do sistema - a primeira parte do título de cada página - é definido em {link}, porque vale para todos os módulos.',
            'system_name_moved_link' => 'Sistema -> Marca',
            'system_name_placeholder' => 'ex. Sistema de Tickets da Central de Serviços',
            'system_name_help' => 'Mostrado no início do título de cada página - o nome na aba do navegador e nos favoritos. Em branco significa "Service Desk".',
            'reopen_label' => 'Reabertura',
            'reopen_toggle' => 'Reabrir um ticket fechado quando o solicitante responder',
            'snooze_hour_label' => 'Início do dia de trabalho',
            'snooze_hour_help' => 'O horário em que um ticket adiado para "Amanhã" ou "Semana que vem" volta. Lido no fuso horário de cada analista, então uma equipe espalhada por vários fusos tem cada uma a sua manhã.',
            'collapse_heading' => 'Mensagens longas',
            'collapse_desc' => 'E-mails longos enterram o motivo pelo qual você abriu o ticket. Mensagens maiores que o limite abaixo são reduzidas com um link Mostrar mais. Nada é excluído — a mensagem completa está sempre a um toque de distância.',
            'collapse_enabled_label' => 'Reduzir mensagens longas',
            'collapse_lines_label' => 'Reduzir mensagens com mais de cerca de',
            'collapse_lines_help' => 'linhas. Uma mensagem que ultrapassa o limite por pouco é deixada como está, para que o link nunca apareça por causa de duas palavras.',
            'collapse_newest_label' => 'Sempre mostrar a mensagem mais recente por completo',
            'collapse_newest_help' => 'A mensagem que você veio ler nunca é reduzida.',
            'collapse_quoted_label' => 'Reduzir histórico citado',
            'collapse_quoted_help' => 'Uma resposta curta com uma longa cadeia de citações abaixo dela é breve em qualquer contagem de linhas e ainda assim ilegível, por isso o histórico citado é reduzido separadamente.',
            'collapse_remember_label' => 'Lembrar o que eu abri',
            'collapse_remember_help' => 'As mensagens que você expande permanecem expandidas neste dispositivo, para que percorrer uma conversa não se desfaça a cada atualização.',
            'group_older_label' => 'Recolher mensagens mais antigas',
            'group_older_help' => 'Além do número abaixo, as mensagens mais antigas são recolhidas em uma única linha que você pode abrir. Um ticket longo é um problema diferente de uma mensagem longa.',
            'group_show_label' => 'Manter esta quantidade de mensagens recentes abertas',
            'flag_duplicates_label' => 'Sinalizar mensagens que já chegaram antes',
            'flag_duplicates_help' => 'Um reenvio, uma entrega duplicada ou uma devolução que traz o original de volta é recolhido com uma nota indicando a qual mensagem corresponde. Nada é excluído.',
            'team_folders_heading' => 'Pastas de equipe',
            'team_folders_label' => 'Os analistas veem',
            'team_folders_all' => 'Todas as equipes',
            'team_folders_mine' => 'Somente as equipes a que pertencem',
            'team_folders_help' => 'Altera apenas a lista de pastas - ninguém perde a visão de um ticket. Uma equipe com tickets que o analista pode ver continua aparecendo, para que as pastas sempre batam. Os administradores sempre veem todas as equipes.',
            'watch_heading' => 'Acompanhamento de tickets',
            'watch_help' => 'Sobre o que os observadores de um ticket são avisados. As configurações de notificação de cada observador continuam valendo além destas.',
            'watch_inactive_label' => 'Quando um observador é desativado',
            'watch_inactive_stop' => 'Parar de avisá-lo - manter seus acompanhamentos para caso volte',
            'watch_inactive_remove' => 'Removê-lo de todos os tickets que acompanha',
            'watch_inactive_help' => 'Um analista desativado nunca é avisado de nada. Parar mantém os acompanhamentos dele ocultos e os restaura se o analista for ativado de novo; Remover os exclui quando o analista é desativado. A remoção vale a partir do momento em que isto é salvo.',
            'watch_event_ticket_reply_received' => 'O solicitante responde',
            'watch_event_ticket_note_added' => 'Uma nota é adicionada',
            'watch_event_ticket_status_changed' => 'O status muda',
            'watch_event_ticket_priority_changed' => 'A prioridade muda',
            'watch_event_ticket_assigned' => 'O ticket é reatribuído',
            'watch_event_sla_warning' => 'Ele se aproxima da meta de SLA',
            'watch_event_sla_breached' => 'Ele descumpre a meta de SLA',
            'ai_heading' => 'AI reading aids',
            'ai_desc' => 'Optional, and off until you turn them on: unlike everything else on this page these use your own AI provider and cost money per use. The provider, model and API key are configured once on the Reply cleanup tab. Nothing an AI writes ever replaces the ticket — the conversation stays exactly where it is, in full.',
            'ai_summary_label' => 'Keep a short AI summary at the top of each ticket',
            'ai_summary_help' => 'A few lines saying where the ticket stands, written on request and kept up to date. It always shows when it was written, how much it read, and how far the conversation has moved on since. Every version is kept, so a worse summary never destroys a better one.',
            'ai_auto_label' => 'Refresh it automatically after this many new messages',
            'ai_auto_help' => '0 means never — the Refresh button is then the only way, and nothing is ever charged without somebody asking. A refresh only happens when an analyst opens the ticket, so a busy queue nobody is reading costs nothing.',
            'ai_max_label' => 'Messages to read',
            'ai_max_help' => 'How far back a summary reads. A longer ticket is read from its most recent end, and the summary says so rather than describing a beginning it never saw.',
            'ai_notes_label' => 'Let it read internal notes',
            'ai_notes_help' => 'Internal notes often hold what was actually tried. They are staff-only either way — the summary is never shown to a requester — but turn this off if notes on your desk hold things that should not leave it.',
            'ai_read_label' => 'Oferecer "Ler para mim" em um ticket',
            'ai_confidential_label' => 'Tickets confidenciais e IA',
            'ai_confidential_block' => 'Nunca enviá-los à IA (recomendado)',
            'ai_confidential_allow' => 'Tratá-los como qualquer outro ticket',
            'ai_confidential_help' => 'Abrange todo recurso de IA que lê um ticket: o resumo, Ler para mim, revisão de respostas, Perguntar à IA, resumos de mesclagem, textos de conhecimento, resumos de canais, análise de problemas e o bot da war room. Um ticket confidencial ou não é enviado ou - onde muitos tickets são lidos de uma vez - fica de fora ou aparece só pelo número.',
            'ai_read_help' => 'A button that reads the whole ticket and briefs you on it: what happened, what is unresolved, and what it would do next. Asked for and read once, stored nowhere.',
            'reopen_help' => 'Vale para qualquer forma de retorno do solicitante — o portal de autoatendimento, uma resposta ao seu e-mail de notificação, WhatsApp ou chat do site. O ticket volta para o seu primeiro status aberto. Apenas tickets em um status marcado como fechado são afetados (defina quais em Status).',
            'location_label' => 'Local de um novo ticket',
            'location_toggle' => 'Usar o local do solicitante',
            'location_help' => 'Um novo ticket começa com o local do solicitante (do registro dele), por qualquer via - e-mail, portal, chat, API. Os analistas podem alterá-lo no ticket. Mudanças posteriores do solicitante não alteram tickets antigos.',
