        'privacy' => [
            'third_party_label' => 'Mensagens enviadas a alguém que não seja o solicitante',
            'opt_hide' => 'Ocultá-las do solicitante',
            'opt_hide_help' => 'A mensagem e seus anexos não aparecem no portal do solicitante. Recomendado: a maioria das pessoas presume que encaminhar um ticket a um fornecedor é privado.',
            'opt_no_attachments' => 'Mostrar a mensagem, mas não os anexos',
