            'opt_show' => 'Mostrar tudo',
            'opt_show_help' => 'O solicitante vê o ticket inteiro exatamente como seus analistas veem, incluindo encaminhamentos e respostas de terceiros. Era assim que funcionava antes desta configuração existir.',
            'always_visible_note' => '<strong>Sempre visível para o solicitante:</strong> as próprias mensagens dele e qualquer resposta endereçada a ele. <strong>Nunca visível:</strong> notas internas — elas ficam ocultas no portal independentemente desta configuração. Mensagens do WhatsApp e do chat do site são sempre exibidas, porque essas conversas são, por definição, entre o solicitante e a sua equipe.',
