        'reply_cleanup' => [
            'intro1' => 'Quando um analista digita uma resposta rascunho no modal de composição do ticket, o botão <strong>✨ Limpeza</strong> a reescreverá como um e-mail devidamente formatado — adicionando uma saudação "Prezado(a) [name]," corrigindo a gramática, aplicando o tom escolhido abaixo e finalizando com "Atenciosamente,". Ele <strong>não</strong> inventará detalhes técnicos nem encherá o conteúdo.',
            'intro2' => 'Este recurso usa sua própria chave de API da Anthropic (separada da IA de RFP e da IA de Conhecimento) para que seu uso apareça como uma linha distinta no painel de cobrança da Anthropic.',
