        'csat_tab' => [
            'intro1' => 'Quando um ticket é fechado, envie ao solicitante um breve e-mail de pesquisa pedindo que avalie a experiência de 1&ndash;5. As respostas são registradas em relação ao analista que fechou o ticket, para que você possa extrair tendências de CSAT por analista, e ficam disponíveis como um widget no painel.',
            'intro2' => 'O e-mail de pesquisa é configurado em <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">Modelos de e-mail</a> &mdash; crie um modelo com o evento <strong>Pesquisa CSAT</strong> e incorpore <code>[csat_link]</code> no corpo para inserir a URL de avaliação de uso único.',
            'mode_off' => 'Desativado',
