            'mode_auto' => 'Automático ao fechar',
            'mode_auto_help' => 'Uma pesquisa é enviada automaticamente quando um ticket passa para qualquer status fechado.',
            'mode_manual' => 'Apenas manual',
            'mode_manual_help' => 'Os analistas clicam em <em>Feedback</em> na barra de ferramentas do ticket quando quiserem perguntar.',
            'delay_help' => 'Aguarde esta quantidade de minutos após o fechamento antes de enviar. <code>0</code> = imediato. Útil se você quiser que o usuário verifique se a correção realmente se manteve antes de ser solicitado a avaliá-la.',
            'reminder' => 'Enviar um lembrete se a pesquisa não for respondida',
            'reminder_hours' => 'Lembrar após (horas)',
            'reminder_help' => 'No máximo um lembrete, por e-mail, com o mesmo link - assim qualquer um dos e-mails funciona e apenas uma avaliação é mantida. Só são lembradas as pesquisas enviadas por e-mail, tenham sido enviadas ao fechar ou pelo botão <strong>Feedback</strong>. Não é enviado se o ticket for reaberto ou estiver na lixeira quando o lembrete vencer. Usa o modelo de e-mail <strong>Lembrete de CSAT</strong>, se você tiver um; caso contrário, usa de novo o modelo da pesquisa. Enviado pela tarefa em segundo plano <em>Pesquisas de satisfação e lembretes atrasados</em>. Ativar isto não lembra as pessoas de pesquisas antigas: apenas daquelas cujo lembrete vence a partir de agora.',
            'one_per_ticket' => 'Uma pesquisa por ticket',
            'one_per_ticket_help' => 'Se ativado, um ticket reaberto e fechado novamente só recebe outra pesquisa quando um analista a aciona manualmente &mdash; evita o envio repetido de pesquisas para um ticket instável.',
            'in_channel' => 'Perguntar aos clientes de chat no próprio chat',
            'in_channel_help' => 'Um cliente que escreveu pelo WhatsApp, Telegram, Slack, Teams ou Mattermost é questionado nesse chat &mdash; com botões onde o aplicativo os oferece, &ldquo;responda de 1 a 5&rdquo; onde não &mdash; em vez de por e-mail. No WhatsApp apenas enquanto a janela de 24 horas está aberta; caso contrário, e se uma mensagem de chat falhar, a pesquisa por e-mail é usada.',
