    'help' => [
        'case' => [
            'nav' => 'Relatórios do caso',
            'heading' => 'Relatórios do caso',
            'intro' => 'Quando um revisor ou auditor pergunta como um caso foi tratado, <strong>Exportar</strong> reúne o ticket, sua conversa e as tarefas que fizeram o trabalho em um único documento imprimível - ninguém precisa copiar tudo à mão.',
            'step1' => '<strong>Abra o ticket</strong> e escolha <strong>Exportar</strong> na barra de ferramentas (em <strong>Mais</strong> quando o painel de leitura está estreito). O relatório abre em uma nova aba. Para uma tarefa sem ticket, use o botão de documento no topo da janela da tarefa.',
            'step2' => '<strong>Marque o que incluir</strong> no painel à esquerda. O relatório é redesenhado conforme você marca, e nada é registrado enquanto você escolhe.',
            'step3' => '<strong>Escolha o layout</strong>: uma capa, uma página de sumário, cada seção em uma nova página e um cabeçalho com números de página.',
            'step4' => '<strong>Imprima</strong> e depois escolha <em>Salvar como PDF</em> na caixa de impressão. Desmarque <em>Cabeçalhos e rodapés</em> do próprio navegador - o relatório imprime os seus.',
            'contents' => '<strong>O que entra:</strong> uma visão geral do ticket (com seus campos personalizados, ativos vinculados, itens de configuração e tickets relacionados); todas as mensagens, da mais antiga para a mais recente; as notas; as listas de verificação do ticket; cada tarefa vinculada com suas subtarefas, resultados de listas de verificação e notas de exceção, respostas de formulários, procedimentos seguidos, acompanhamentos e comentários; o histórico do ticket e de cada tarefa; e um índice dos documentos e anexos de e-mail, com a impressão digital que o FreeITSM registrou para cada documento.',
            'layout' => '<strong>Layout:</strong> a página de sumário lista todas as seções e tarefas, e cada item é um link no PDF salvo. O cabeçalho e os números de página (<em>Página 3 de 12</em>) exigem um Chrome ou Edge atual; outros navegadores imprimem o relatório sem eles.',
            'who' => '<strong>Quem vê o quê:</strong> o relatório mostra apenas o que você poderia ver na tela. Tarefas, ativos, itens de configuração, tickets relacionados, documentos e respostas de formulários são verificados cada um com sua própria regra, e tudo o que você não pode ver é <em>contado</em> - nunca nomeado - para que o leitor saiba que algo ficou de fora. <strong>Notas internas ficam de fora, a menos que você as marque</strong>, porque um relatório normalmente sai da equipe.',
            'recorded' => '<strong>O que é registrado:</strong> imprimir grava uma linha <em>Relatório do caso</em> na trilha de auditoria do ticket, com quem imprimiu e quais seções foram incluídas. Visualizar e alterar as opções não registra nada.',
            'note' => 'Um relatório do caso é uma cópia do registro, não um texto redigido: nada é reescrito ou resumido, imagens dentro de e-mails não são reproduzidas, arquivos são listados em vez de incluídos, e só aparece o histórico que o FreeITSM realmente registrou. Uma seção que não pode ser lida avisa em vermelho, em vez de parecer vazia.',
        ],
        'workspace' => [
            'nav' => 'Espaço de trabalho e tabela de tickets',
            'heading' => 'O espaço de trabalho e a tabela de tickets',
            'intro' => 'Duas outras formas de trabalhar com tickets, ambas opcionais. O <strong>espaço de trabalho</strong> organiza um ticket para trabalhar, não só para ler. A <strong>tabela de tickets</strong> mostra a lista de tickets como uma tabela que você pode filtrar, ordenar e salvar.',
            'ws_title' => 'O espaço de trabalho',
            'ws_what' => 'No espaço de trabalho, as propriedades do ticket ficam em uma coluna à esquerda, e sua <strong>Conversa</strong>, <strong>Trabalho</strong> (listas de verificação, formulários e tarefas vinculadas), <strong>Links</strong>, <strong>Tempo e SLA</strong> e <strong>Histórico</strong> são abas ao lado. A barra de ferramentas e todos os controles são os mesmos do painel de leitura - só muda onde ficam. A <strong>lista de verificação</strong> do próprio ticket mostra todas as etapas com sua caixa de seleção na aba Trabalho; <strong>Recolher</strong> mostra apenas a próxima etapa (lembrado no seu navegador), e <strong>Destacar</strong> ainda a abre em uma janela própria.',
            'ws_admin' => '<strong>Um administrador ativa</strong> em <strong>Tickets &rarr; Configurações &rarr; Geral &rarr; Espaço de trabalho do ticket</strong>: <em>Desativado</em> (o padrão), <em>Apenas tickets transformados em espaço de trabalho</em> ou <em>Todos os tickets</em>.',
            'ws_make' => '<strong>Transformar um ticket em espaço de trabalho:</strong> na opção intermediária, abra o ticket e escolha <strong>Mais &rarr; Criar espaço de trabalho</strong> (e <strong>Voltar ao painel de leitura</strong> para desfazer). Isso pertence ao ticket, então todos que trabalham nele o veem do mesmo jeito, e fica registrado no histórico do ticket.',
            'ws_own' => '<strong>Sua própria escolha:</strong> depois de ativado, <strong>Usar o espaço de trabalho</strong> no menu de filtros da lista, ou em <strong>Sistema &rarr; Preferências</strong>, o desativa só para você. Um ticket transformado em espaço de trabalho passa a mostrar um pequeno selo <em>Espaço de trabalho</em>, para você saber que um colega está trabalhando nele assim.',
            'ws_checklist' => '<strong>As listas de verificação do ticket mostram todas as etapas:</strong> na aba <strong>Trabalho</strong>, uma lista de verificação mostra todas as suas etapas com as caixas de seleção. <strong>Recolher</strong> a reduz à próxima etapa, como o painel de leitura mostra, e <strong>Expandir</strong> traz o restante de volta - seu navegador lembra o que você escolheu. <strong>Destacar</strong> ainda abre a lista completa em uma janela.',
            'ws_tasks' => '<strong>Tarefas vinculadas abrem no próprio lugar:</strong> clique em uma tarefa na aba <strong>Trabalho</strong> e o editor dela abre ali - incluindo listas de verificação, formulários, procedimentos, subtarefas, comentários e documentos. <strong>Abrir separadamente</strong> a abre em uma janela própria, como antes; Ctrl+clique faz o mesmo. Você precisa de acesso a Tarefas para editá-la.',
            'ws_safe' => '<strong>Nada do que foi digitado se perde:</strong> ir para outro ticket, ou desativar o espaço de trabalho, com uma resposta, uma nota ou uma alteração de tarefa não salva, pergunta antes e espera qualquer coisa que ainda esteja sendo salva.',
            'tb_title' => 'A tabela de tickets',
            'tb_what' => 'Escolha <strong>Tabela</strong> em vez de <strong>Mensagens</strong> na linha de ações no topo de Tickets (ou em <strong>Sistema &rarr; Preferências</strong>). A pasta em que você está se torna o filtro da tabela; escolha colunas, filtre e ordene, pesquise e percorra a lista de 25, 50 ou 100 tickets por vez. <strong>Salvar exibição</strong> guarda um layout para você, sua equipe ou todos.',
            'tb_remember' => 'A tabela lembra a exibição que você escolheu por último e abre com ela na próxima vez, em qualquer navegador - até você escolher outra ou usar <strong>Redefinir</strong>, depois do que ela abre novamente com sua exibição padrão. Aberta a partir de uma pasta que já restringe a lista - um departamento, equipe, analista, status ou Não atribuído - a pasta prevalece, e só uma exibição padrão a substitui.',
            'tb_same' => 'Clicar, Ctrl+clique e Shift+clique, clicar com o botão direito, arrastar para uma pasta e as ações em massa funcionam como na lista de mensagens, e a tabela nunca mostra um ticket que a lista não mostraria.',
            'tb_export' => '<strong>Exportação CSV:</strong> o botão CSV exporta <em>todos</em> os tickets que correspondem, não só a página, com as colunas que você está exibindo. Quem pode usá-lo é definido em <strong>Tickets &rarr; Configurações &rarr; Geral &rarr; Quem pode exportar a lista de tickets</strong>: somente administradores (o padrão), qualquer pessoa com Tickets ou ninguém. O botão não aparece para quem não tem acesso a ele.',
            'tb_columns' => '<strong>Para quem é um ticket:</strong> as colunas <strong>Solicitante</strong> e <strong>E-mail do solicitante</strong> mostram a pessoa para quem o ticket foi aberto e o endereço de e-mail dela. Ficam ocultas até você marcá-las em <strong>Colunas</strong>; ambas podem ser ordenadas e ambas entram na exportação CSV quando estão visíveis.',
        ],
        'page_title' => 'Central de Serviços - Guia de Tickets',
        'sidebar_title' => 'Guia',
        'hero_title' => 'Guia do módulo de Tickets',
        'hero_sub' => 'Registre, acompanhe e resolva solicitações de suporte de TI a partir de uma única caixa de entrada baseada em pastas &mdash; feito para equipes de central de serviços.',
        'nav' => [
            'overview' => 'Visão geral',
            'inbox' => 'A caixa de entrada',
            'working_with_tickets' => 'Trabalhando com tickets',
            'working_faster' => 'Trabalhando mais rápido',
            'comments_attachments' => 'Comentários &amp; anexos',
            'ai_tools' => 'Ferramentas de IA',
            'csat' => 'Pesquisas CSAT',
            'user_management' => 'Gerenciamento de usuários',
            'dashboard' => 'Painel',
            'calendar_rota' => 'Calendário &amp; escala',
            'settings' => 'Configurações',
            'tips' => 'Dicas rápidas',
            'companies' => 'Empresas',
        ],
        'overview' => [
            'heading' => 'Visão geral',
            'intro' => 'O módulo de Tickets é o núcleo da sua central de serviços de TI. Ele oferece uma interface familiar no estilo de cliente de e-mail para gerenciar solicitações de suporte, incidentes e tarefas de serviço. Os tickets chegam de usuários finais por e-mail ou criação manual, e os analistas trabalham neles usando pastas, prioridades e cronômetros de SLA &mdash; tudo o que você precisa para oferecer um suporte de TI ágil.',
            'card_inbox_title' => 'Caixa de entrada',
            'card_inbox_body' => 'Uma caixa de entrada baseada em pastas inspirada em um cliente de e-mail. Navegue pelas pastas Meus Tickets, Não Atribuídos, Todos Abertos e Fechados. Clique em qualquer ticket para abrir um painel de leitura com todos os detalhes, histórico e ações.',
            'card_dashboard_title' => 'Painel',
            'card_dashboard_body' => 'Monte um painel personalizado com widgets Chart.js customizáveis. Visualize volumes de tickets, tempos de resposta, divisões por categoria e cargas de trabalho dos analistas com gráficos de barras, pizza, rosca e linha.',
            'card_calendar_title' => 'Calendário',
            'card_calendar_body' => 'Veja os tickets em uma grade de calendário com base nas datas de criação, vencimento ou resolução. Identifique rapidamente itens em atraso e planeje sua semana visualizando o panorama dos tickets de relance.',
            'card_rota_title' => 'Escala',
            'card_rota_body' => 'Agende turnos dos analistas e escalas de plantão. Veja quem está disponível a qualquer momento, planeje a cobertura para fins de semana e feriados e garanta que nenhum ticket fique sem atendimento.',
        ],
        'inbox' => [
            'heading' => 'A caixa de entrada',
            'intro' => 'A caixa de entrada é o principal espaço de trabalho dos analistas. Ela usa um layout de três painéis &mdash; pastas à esquerda, uma lista de tickets ao centro e um painel de leitura à direita &mdash; para que você possa fazer a triagem e responder sem nunca sair da página.',
            'p_live' => '<strong>Ela se mantém atualizada sozinha.</strong> A cada minuto a caixa de entrada verifica suas caixas postais e procura novidades nos tickets que você pode ver &mdash; um e-mail coletado em segundo plano, uma mensagem de WhatsApp, Telegram, Slack, Teams ou Mattermost, a resposta de um colega &mdash; e, quando algo chega, a lista e as contagens das pastas são atualizadas por conta própria, como faz o botão de atualizar. O ticket que você está lendo e qualquer resposta que esteja digitando não são afetados.',
            'p_folders' => 'O painel de pastas organiza os tickets em grupos lógicos. Cada pasta mostra uma contagem de não lidos para você identificar novos trabalhos imediatamente:',
            'field_my' => '<strong>Meus Tickets</strong> &mdash; tickets atribuídos a você. Esta é sua fila pessoal e o melhor lugar para começar cada dia.',
            'field_unassigned' => '<strong>Não Atribuídos</strong> &mdash; tickets que chegaram, mas ainda não têm analista. Pegue itens daqui para assumir a responsabilidade.',
            'field_all_open' => '<strong>Todos Abertos</strong> &mdash; todos os tickets que ainda não foram fechados, independentemente de quem os possui. Útil para gestores e líderes de equipe que monitoram o volume geral.',
            'field_closed' => '<strong>Fechados</strong> &mdash; tickets resolvidos. Pesquise aqui quando precisar consultar uma solução anterior ou reabrir um problema.',
            'field_dept' => '<strong>Pastas de departamento</strong> &mdash; tickets agrupados por departamento (ex. TI, RH, Financeiro). Os departamentos são configurados nas Configurações e aparecem como subpastas automaticamente.',
            'switch_heading' => '<strong>Alternando entre o agrupamento por Departamento e por Analista</strong>',
            'switch_body' => 'Um pequeno botão de alternância com duas opções no topo do painel de pastas alterna entre duas visualizações dos mesmos dados. O agrupamento por <strong>Departamento</strong> (padrão) lista os tickets sob cada departamento com subpastas de status dentro; o agrupamento por <strong>Analista</strong> inverte isso, de modo que cada pasta de nível superior representa a fila pessoal de um analista com subpastas de status dentro. A pasta <strong>Não Atribuídos</strong> é sensível ao contexto em cada visualização &mdash; na visão de Departamento, ela lista os tickets sem departamento definido; na visão de Analista, ela lista os tickets sem responsável &mdash; assim você sempre vê o que precisa ser assumido. Sua escolha é salva por analista, para que cada membro da equipe mantenha a visualização que prefere entre as sessões.',
            'folders_hide' => '<strong>Precisa de mais espaço?</strong> Pressione <strong>[</strong> (quando não estiver digitando), ou o <strong>&laquo;</strong> no topo do painel de pastas, para recolhê-lo em uma faixa fina; pressione <strong>[</strong> ou clique na faixa para trazê-lo de volta. Para que fique recolhido sempre, escolha <strong>Clique para abrir</strong> ou <strong>Mostrar ao passar o mouse</strong> em <em>Tickets - pastas</em> em Preferências &rarr; Exibição &rarr; Painéis esquerdos. Recolhidas, as pastas abrem sobre a lista de tickets e fecham de novo quando você escolhe uma. Em um celular, as pastas funcionam como antes.',
            'folders_narrow' => '<strong>Em uma janela estreita</strong> (1100px de largura ou menos, como um tablet), as pastas começam recolhidas mesmo em <strong>Sempre visível</strong>, e a lista de tickets estreita um pouco, para que o ticket que você está lendo tenha espaço. Aumente a janela e elas voltam.',
            'p_actions' => 'Acima da lista de tickets, há quatro botões de ação: <strong>Novo</strong> para criar um ticket, <strong>Pesquisar</strong> para encontrar tickets por palavra-chave, referência ou solicitante, <strong>Filtrar</strong> para restringir o que você vê e <strong>Atualizar</strong> para recarregar a pasta atual.',
            'filter_body' => 'O botão <strong>Filtrar</strong> (o funil) restringe as pastas e a lista ao mesmo tempo, qualquer que seja o agrupamento. <strong>Meus</strong> mostra apenas os tickets atribuídos a você, e <strong>Ocultar fechados</strong> deixa de fora todo ticket cujo status esteja marcado como fechado. Enquanto um filtro está ativo, o funil exibe um ponto e um rótulo aparece ao lado do título da lista, para você saber sempre que não está vendo tudo. Quando as pastas são agrupadas por <strong>Analista</strong>, sua própria pasta fica no topo como <strong>Meus tickets</strong>. A pesquisa tem a própria opção <strong>Incluir tickets fechados</strong>, ativada por padrão, porque uma pesquisa costuma ser a busca por um ticket antigo. As duas escolhas são salvas só para você.',
            'row_name' => 'Cada linha mostra a referência do ticket e depois um nome. Por padrão, esse é <strong>a pessoa que abriu o ticket</strong>, e permanece o mesmo durante toda a vida do ticket. Se você preferir ver quem enviou a mensagem mais recente &mdash; que se torna a sua própria caixa postal depois que você responde &mdash; altere <strong>Nome ao lado do número do ticket</strong> em <strong>Configurações &rarr; Exibição de linhas</strong>, onde também é possível ocultar o nome e deixar apenas a referência. Essa aba é uma configuração sua: ela não muda nada para mais ninguém.',
            'tip' => 'Clique em qualquer ticket na lista para carregá-lo no painel de leitura. A partir dali, você pode atualizar campos, adicionar comentários, responder por e-mail ou anexar arquivos &mdash; tudo sem sair da caixa de entrada.',
        ],
        'live' => [
            'heading' => 'Atualizações ao vivo',
            'body' => 'O FreeITSM mantém sua tela em sincronia com todos os outros. Quando um colega altera um ticket - seu status, prioridade, responsável ou equipe, uma resposta, uma nota - sua lista de tickets e o ticket que você tem aberto se atualizam em cerca de 15 segundos, sem precisar atualizar a página. O quadro de tarefas, uma tarefa aberta e o sino funcionam da mesma forma.',
            'what' => 'Ele só verifica enquanto a aba está à sua frente e se atualiza no instante em que você volta a ela. Uma alteração feita em uma aba aparece nas suas outras abas imediatamente.',
            'safe' => 'Nunca descarta o que você está fazendo. Enquanto você escreve uma resposta ou uma nota, digita em um campo ou tem um menu aberto, novas mensagens ainda aparecem na conversa, e o resto espera atrás de um pequeno aviso <strong>Atualizado por outra pessoa agora mesmo &middot; Atualizar</strong>.',
            'setting' => '<strong>Preferências &rarr; Atualizações ao vivo</strong> escolhe a cada 15 segundos (o padrão), 30 segundos, a cada minuto ou desativado.',
        ],
        'watch' => [
            'heading' => 'Acompanhando um ticket',
            'body' => 'Acompanhe um ticket sem ser o responsável - um líder de equipe de olho em um incidente grave, ou o analista que o repassou. Os seguidores são avisados sobre o ticket como se fosse deles, pelas próprias configurações de notificação.',
            'how' => '<strong>Acompanhar</strong> na barra de ferramentas do ticket, ou clique com o botão direito nele na lista e escolha <strong>Acompanhar</strong>. Clique com o botão direito em uma seleção para acompanhar todos. Em um ticket que você já acompanha, o botão da barra de ferramentas e o menu do botão direito mostram <strong>Parar de acompanhar</strong> - uma seleção pode ser acompanhada, mas não deixada de acompanhar de uma só vez.',
            'others' => 'O botão <strong>Acompanhar</strong> mostra quem está acompanhando. Com acesso de gravação a Tickets você pode <strong>adicionar um colega</strong> ou remover alguém; qualquer pessoa pode remover a si mesma.',
            'what' => '<strong>Tickets &rarr; Configurações &rarr; Geral &rarr; Acompanhamento de tickets</strong> escolhe sobre o que os seguidores são avisados - respostas, notas, status, prioridade, reatribuição, avisos e violações de SLA - tudo, a menos que um administrador desmarque algo. Uma reatribuição chega ao seguidor como "reatribuído", nunca como "atribuído a você", e tem seu próprio interruptor nas preferências de cada pessoa.',
            'leaver' => 'Um analista desativado nunca é avisado sobre um ticket que acompanha. <strong>Tickets &rarr; Configurações &rarr; Geral &rarr; Quando um seguidor é desativado</strong> decide o que acontece com os acompanhamentos dele: <strong>Parar</strong> (o padrão) os mantém fora de vista e os restaura se o analista for reativado; <strong>Remover</strong> tira o analista de todos os tickets que ele acompanha quando é desativado.',
            'note' => 'Só quem pode ver um ticket pode acompanhá-lo, e quem deixa de poder vê-lo deixa de ser avisado. Ninguém é avisado sobre a própria alteração. Mesclar move os seguidores para o ticket que permanece.',
        ],
        'forms_on_ticket' => [
            'heading' => 'Formulários em um ticket',
            'body' => 'Anexe um formulário do módulo Formulários a um ticket e preencha-o ali - uma solicitação de novo funcionário que precisa do formulário de equipamentos, ou um incidente de segurança que precisa do seu relatório. As respostas ficam guardadas com o ticket.',
            'switch' => '<strong>Tickets &rarr; Configurações &rarr; Listas de verificação &rarr; Formulários em tickets</strong> o ativa (fica desativado até você fazer isso, e o módulo Formulários também precisa estar ativado). Um botão <strong>Formulários</strong> aparece então na barra de ferramentas de cada ticket, com a contagem de quantos foram enviados. Em um espaço de trabalho, os formulários também aparecem na aba <strong>Trabalho</strong>. Clique com o botão direito em um ticket, ou em uma seleção, e escolha <strong>Adicionar formulário</strong> para adicionar um sem abri-lo.',
            'how' => '<strong>Formulários</strong> abre a lista: <strong>Adicionar</strong> escolhe um formulário (sempre a versão mais recente), <strong>Preencher</strong> o abre em uma janela, <strong>Salvar rascunho</strong> guarda respostas incompletas que colegas podem continuar, e <strong>Corrigir</strong> substitui um envio mantendo o antigo em Formulários.',
            'required' => 'Cada formulário é <strong>Obrigatório - bloqueia o fechamento</strong>, <strong>Obrigatório - avisa ao fechar</strong> ou <strong>Opcional</strong>. Um formulário bloqueante precisa ser enviado antes que o ticket possa chegar a um status fechado; um de aviso pergunta e registra quem fechou mesmo assim.',
            'note' => 'Preencher um formulário exige acesso de gravação a Formulários e a Tickets. Ler as respostas exige acesso a Formulários ou a permissão <strong>Ler as respostas de formulários nos tickets que você pode ver</strong> (uma configuração de função); todos os outros veem quem enviou e quando, mas não o que foi dito. Um envio do qual um ticket depende não pode ser excluído de Formulários. As respostas aparecem no relatório do caso do ticket e na API REST.',
        ],
        'faster' => [
            'heading' => 'Trabalhando mais rápido',
            'intro' => 'Quatro coisas que transformam uma manhã cheia em algo gerenciável: respostas salvas, agir em vários tickets de uma vez e colocar as conversas onde elas pertencem.',
            'templates_heading' => 'Respostas prontas',
            'templates_body' => 'Você envia sempre as mesmas respostas. Escreva uma vez e clique em <strong>Modelos</strong>, no canto inferior esquerdo da janela de resposta, para inseri-la onde está o cursor &mdash; ela é acrescentada ao que você já digitou, sem substituir. Os modelos são em rich text e aceitam os mesmos marcadores <code>[merge_code]</code> dos e-mails automáticos, então <code>[requester_first_name]</code> vira o nome real no momento da inserção.',
            'templates_team' => '<strong>Modelos da equipe</strong> &mdash; compartilhados com todos, configurados em Configurações &rarr; Modelos de resposta.',
            'templates_mine' => '<strong>Os seus</strong> &mdash; salve um rascunho com <em>Salvar rascunho como modelo</em>. Particular e sem necessidade de permissão.',
            'templates_tip' => 'Dê ao modelo um nome pela situação ("Impressora offline &mdash; primeiros passos"), não pelo texto. É o que você vai procurar às 9h.',
            'select_heading' => 'Selecionar vários tickets',
            'select_body' => 'A lista de tickets funciona como o Outlook ou o Explorador de Arquivos. Sem caixas de seleção.',
            'key_click' => 'Clique',
            'key_click_d' => 'seleciona um e o abre',
            'key_ctrl' => 'Ctrl+clique',
            'key_ctrl_d' => 'adiciona ou remove um, sem mexer nos demais',
            'key_shift' => 'Shift+clique',
            'key_shift_d' => 'seleciona um bloco inteiro a partir do último clique',
            'key_kb' => 'Teclado',
            'key_kb_d' => 'setas para mover, Shift+setas para estender, Ctrl+setas e Espaço para escolher tickets avulsos, Ctrl+A para tudo, Esc para limpar',
            'select_actions' => 'Com vários selecionados, <strong>clique com o botão direito em qualquer um</strong> para definir status, prioridade, departamento, tipo ou responsável de todos de uma vez &mdash; ou arraste o conjunto para uma pasta. O que a tela mostra enquanto vários estão selecionados é escolha sua, no menu da conta em Preferências.',
            'select_tip' => 'Clicar com o botão direito em um ticket que <em>não</em> está na seleção limpa a seleção e mira apenas nele. Isso é proposital &mdash; você nunca age sobre um conjunto que achava ter deixado para trás.',
            'merge_heading' => 'Mesclar duplicados',
            'merge_body' => 'Duas pessoas relataram a mesma queda? Selecione os tickets, clique com o botão direito, <strong>Mesclar</strong>. As conversas se juntam e, se houver um provedor de IA configurado, o FreeITSM escreve um resumo do que cada um pediu e do que já foi feito, para quem assumir não precisar ler quatro conversas.',
            'merge_tip' => 'Nada é excluído. O ticket mesclado mantém sua referência, continua pesquisável, mostra para onde foi &mdash; e um cliente que responder a um e-mail antigo ainda chega até você.',
            'split_heading' => 'Dividir um ticket',
            'split_body' => 'O trabalho oposto. Quando alguém levanta um segundo assunto no meio da conversa, clique em <strong>Dividir</strong> naquela mensagem (ou botão direito no cabeçalho dela). Ela vai para um novo ticket, opcionalmente levando todas as mensagens mais recentes, e o original mantém uma marca indicando para onde foram.',
            'split_tip' => 'Dê um assunto adequado ao novo ticket. O padrão é o da mensagem movida, que normalmente é um "RE:" do problema <em>antigo</em>.',
            'undo_heading' => 'Mudou de ideia',
            'undo_body' => 'Ambos podem ser desfeitos pelo aviso no ticket. Desfazer uma <strong>divisão</strong> é recusado assim que alguém responde no novo ticket, adiciona uma nota ou registra tempo &mdash; e você é informado exatamente do que está no caminho. Desfazer uma <strong>mesclagem</strong> devolve mensagens, notas e tempo registrado e reabre o ticket exatamente como estava, mas as respostas escritas no outro ticket desde a mesclagem permanecem lá.',
        ],
        'working' => [
            'heading' => 'Trabalhando com tickets',
            'intro' => 'Toda solicitação de suporte segue um ciclo de vida: ela é criada, triada, trabalhada e, por fim, resolvida. O módulo de Tickets oferece as ferramentas para gerenciar cada etapa com eficiência, do registro inicial até o encerramento.',
            'creating_heading' => '<strong>Criando um novo ticket</strong>',
            'step1' => '<strong>Clique em Novo</strong> &mdash; abra a janela de novo ticket na barra de ferramentas da caixa de entrada. Insira o nome e o endereço de e-mail do solicitante para que ele possa receber atualizações.',
            'step2' => '<strong>Defina o assunto</strong> &mdash; escreva um resumo claro e conciso do problema. Ele aparece na lista de tickets e em qualquer notificação por e-mail enviada ao usuário final.',
            'step3' => '<strong>Escolha departamento, tipo e prioridade</strong> &mdash; selecione o departamento, o tipo de ticket (ex. Incidente, Solicitação de Serviço) e o nível de prioridade adequados. Esses campos orientam os cronômetros de SLA e as regras de roteamento.',
            'step4' => '<strong>Adicione a descrição</strong> &mdash; forneça todos os detalhes do problema usando o editor de texto formatado. Inclua passos para reproduzir, mensagens de erro e qualquer contexto relevante de que o analista responsável precisará.',
            'step5' => '<strong>Salve</strong> &mdash; o ticket é criado com um número de referência único e aparece na pasta apropriada. O cronômetro de SLA começa imediatamente com base na prioridade.',
            'editing_heading' => '<strong>Editando e gerenciando tickets</strong>',
            'editing_body' => 'Depois que um ticket existe, você pode atualizar qualquer campo a partir do painel de leitura. Os principais campos incluem:',
            'card_status_title' => 'Status',
            'card_status_body' => 'Acompanhe o ciclo de vida do ticket: Novo, Aberto, Em Andamento, Pendente, Resolvido, Fechado',
            'card_priority_title' => 'Prioridade',
            'card_priority_body' => 'Defina urgência e impacto: Crítica, Alta, Média, Baixa. Cada nível tem sua própria meta de SLA',
            'card_category_title' => 'Categoria',
            'card_category_body' => 'Classifique o tipo de problema: Hardware, Software, Rede, Acesso, Geral. Útil para relatórios',
            'card_analyst_title' => 'Analista atribuído',
            'card_analyst_body' => 'A pessoa responsável por resolver o ticket. A reatribuição é registrada na trilha de atividades',
            'card_enduser_title' => 'Usuário final',
            'card_enduser_body' => 'A pessoa que abriu a solicitação. Pesquise por nome ou e-mail para vincular a um registro de usuário existente',
            'card_dept_title' => 'Departamento',
            'card_dept_body' => 'Encaminhe os tickets para a equipe correta. Os departamentos orientam o agrupamento de pastas e os filtros do painel',
            'flow_new' => 'Novo',
            'flow_in_progress' => 'Em Andamento',
            'flow_resolved' => 'Resolvido',
            'flow_closed' => 'Fechado',
            'triage_heading' => '<strong>Triagem por arrastar e soltar</strong>',
            'triage_body' => 'Você não precisa abrir um ticket para triá-lo. Arraste qualquer linha da lista de tickets até uma pasta para atualizar campos em um único movimento:',
            'triage_dept' => '<strong>Visão de Departamento</strong> &mdash; solte em uma pasta de departamento para reatribuir, solte em uma subpasta de status dentro de um departamento para atualizar ambos de uma vez, solte em <strong>Não Atribuídos</strong> para limpar o departamento.',
            'triage_analyst' => '<strong>Visão de Analista</strong> &mdash; solte na pasta de um analista para atribuí-lo como responsável (define tanto <code>assigned_analyst_id</code> quanto <code>owner_id</code>, para que o campo Responsável no painel de leitura fique sincronizado), solte em uma subpasta de status para atualizar ambos, solte em <strong>Não Atribuídos</strong> para limpar o responsável.',
            'triage_spring' => '<strong>Pastas com expansão automática</strong> &mdash; passe o cursor sobre uma pasta recolhida durante o arraste e ela se expande automaticamente (estilo Outlook), para que qualquer status aninhado fique acessível sem soltar primeiro.',
            'fullscreen_heading' => '<strong>Visualização em tela cheia</strong>',
            'fullscreen_body' => 'Quando você precisa se concentrar em um único ticket &mdash; uma conversa longa, uma mudança complexa, redigir uma resposta detalhada &mdash; alterne para a visualização em tela cheia. A lista de pastas e a lista de tickets desaparecem, a conversa preenche toda a largura disponível, e as propriedades (Departamento, Tipo, Status, Origem, Resolução na Primeira Vez, Treinamento de TI, Responsável) movem-se para uma barra lateral vertical à direita.',
            'fullscreen_max' => '<strong>Ícone de maximizar</strong> &mdash; pequeno ícone na extremidade direita da linha de assunto do ticket. Clique para entrar em tela cheia; clique novamente para voltar ao layout de 3 painéis.',
            'fullscreen_dbl' => '<strong>Clique duplo em uma linha</strong> &mdash; dê um clique duplo em qualquer ticket da lista para abri-lo diretamente em tela cheia, no gesto estilo Outlook de "abrir mesmo este aqui".',
            'fullscreen_sticks' => '<strong>Permanece entre seleções</strong> &mdash; uma vez em tela cheia, alternar para o próximo ticket mantém você nesse modo. Uma recarga da página (F5) sem nenhum ticket selecionado retorna ao layout padrão de 3 colunas, para que você não fique preso com a lista de pastas oculta.',
            'fullscreen_back' => '<strong>Voltar</strong> &mdash; a barra acima do ticket mostra sua referência e um botão <strong>Voltar</strong>, que leva você direto à lista exatamente como você a deixou, com o teclado de volta na lista - assim as setas se movem entre tickets e Enter abre o próximo imediatamente. <strong>Escape</strong> faz o mesmo, depois que qualquer janela ou menu aberto sobre o ticket for fechado. Nenhum dos dois desativa a tela cheia: o próximo ticket ainda abre em tela cheia (o ícone de reduzir é o interruptor), e ao voltar ao ticket que você deixou, qualquer resposta que você tinha começado ainda está lá.',
            'fullscreen_keys' => '<strong>As teclas rolam o ticket</strong> &mdash; em tela cheia, as setas, Page Up / Page Down e Espaço rolam a conversa, não a lista de tickets oculta. Em uma janela de imagem ou PDF, rolam essa janela. Na visualização normal de três painéis, clique no ticket e as teclas o rolam também; clique na lista para voltar a se mover entre tickets.',
            'viewer_heading' => '<strong>Imagens e PDFs abrem sobre o ticket</strong>',
            'viewer_body' => 'Clique em uma imagem ou PDF anexado a uma nota, ou em um da lista de <strong>Anexos</strong> do ticket (sua miniatura ou sua linha), e ele abre em uma janela sobre o ticket &mdash; o mesmo visualizador do módulo Arquivos. O ticket fica exatamente onde estava por baixo.',
            'viewer_window' => '<strong>Mova e redimensione</strong> &mdash; arraste a barra de título para mover a janela e qualquer borda ou canto para redimensioná-la; clique duas vezes na barra de título, ou arraste-a até o topo da tela, para preencher a tela. A imagem ou PDF se reajusta conforme a janela muda de tamanho, até você aplicar zoom por conta própria &mdash; <strong>Ajustar</strong> devolve o controle. Abra várias e elas ficam lado a lado.',
            'viewer_close' => '<strong>Feche</strong> &mdash; o &times; na barra de título, ou <strong>Escape</strong> (que fecha a janela da frente). <strong>Baixar</strong> salva o arquivo. Em um celular, o arquivo abre em tela cheia com um botão Voltar.',
            'viewer_other' => '<strong>Outros arquivos</strong> &mdash; documentos do Word, planilhas e tudo o mais continuam sendo baixados ou abertos em uma nova aba, como antes. Para abrir a imagem ou o PDF de uma nota em uma nova aba, use Ctrl+clique.',
            'paste_heading' => '<strong>Cole uma captura de tela em uma nota</strong>',
            'paste_body' => 'Copie uma captura de tela, clique na caixa <strong>Adicionar nota</strong> e pressione <strong>Ctrl+V</strong>. A imagem entra onde está o cursor, com seu texto antes e depois dela, e continua nesse lugar depois que a nota é salva. Clique nela para abri-la no visualizador. <strong>Backspace</strong> a remove antes de você salvar.',
            'paste_shared' => '<strong>Notas compartilhadas compartilham suas imagens</strong> &mdash; o solicitante as vê no portal, no próprio lugar. Em uma nota interna, elas são tão privadas quanto a nota.',
            'paste_save' => '<strong>Nada é guardado até você pressionar Salvar</strong> &mdash; feche a caixa e as imagens vão com ela. Se uma imagem for recusada, a nota também não é salva, o motivo é mostrado e seu texto continua na caixa.',
            'paste_text' => '<strong>Texto continua texto</strong> &mdash; colar do Word, de uma página da web ou do Excel insere as palavras sem a formatação. O botão <strong>Anexar</strong> continua funcionando para qualquer outro arquivo.',
            'rightclick_heading' => '<strong>Clique com o botão direito para ações rápidas</strong>',
            'rightclick_body' => 'Clique com o botão direito em qualquer ticket da lista para abrir um menu de contexto. O menu mostra a referência do ticket no topo para que você saiba sobre o que está agindo, e cada ação opera sobre o ticket clicado <em>sem</em> alterar o que está aberto no painel de leitura &mdash; útil quando você está lendo o ticket A e precisa triar o ticket B sem perder seu lugar.',
            'rightclick_status' => '<strong>Definir status &rarr;</strong> &mdash; submenu suspenso listando cada status ativo com sua amostra de cor. Uma marca de seleção aparece ao lado do valor atual se você estiver clicando com o botão direito no ticket que tem aberto. As escolhas atualizam o ticket imediatamente, gravam uma entrada na trilha de auditoria, atualizam as contagens das pastas e sincronizam o menu suspenso de Status do painel de leitura, se aplicável.',
            'rightclick_priority' => '<strong>Definir prioridade &rarr;</strong> &mdash; mesmo padrão de submenu, baseado na lista de prioridades ativas, cada uma com sua cor como amostra. A primeira linha é uma opção <em>(sem prioridade)</em> para limpar a atribuição (a prioridade é anulável).',
            'rightclick_assign' => '<strong>Atribuir a &rarr;</strong> &mdash; submenu listando cada analista carregado com uma ficha cinza com a inicial, além de uma linha <em>(não atribuído)</em> no topo para limpar. As escolhas definem tanto <code>assigned_analyst_id</code> QUANTO <code>owner_id</code>, para que o campo Responsável do painel de leitura fique sincronizado.',
            'rightclick_cmdb' => '<strong>Vincular objeto CMDB&hellip;</strong> &mdash; abre um seletor de pesquisa instantânea. Clique em um resultado para vinculá-lo e continue escolhendo &mdash; o campo se limpa e refoca para o próximo, e um registro "Vinculados recentemente" dentro da janela mostra sua lista contínua de confirmações com marca de seleção verde.',
            'rightclick_time' => '<strong>Registrar tempo&hellip;</strong> &mdash; abre uma janela com minutos + um seletor de data/hora (padrão "agora", para que você também possa retroagir) + uma caixa de notas opcional.',
            'rightclick_more' => '<strong>Anexar lista de verificação &rarr;</strong>, <strong>Adicionar formulário &rarr;</strong> e <strong>Acompanhar</strong> - anexe uma lista de verificação (as melhores correspondências primeiro), adicione um formulário ou acompanhe o ticket sem abri-lo. Em uma seleção, atuam em todos os tickets selecionados, ignorando qualquer um que já tenha essa lista de verificação ou formulário.',
            'rightclick_phone' => '<strong>No celular</strong>, mantenha um ticket pressionado por meio segundo para abrir o mesmo menu como um painel em tela cheia. Uma opção com mais alternativas &mdash; Definir status, Definir prioridade, Atribuir a &mdash; desliza para elas, com <strong>Voltar</strong> para retornar.',
            'rightclick_tip' => 'Se o ticket sobre o qual você está agindo pelo menu de contexto for o mesmo que está aberto no painel de leitura, a seção relevante ali (menus suspensos de Status / Prioridade, objetos CMDB, registros de tempo) é atualizada automaticamente quando a janela é fechada, mantendo a interface sincronizada.',
            'time_heading' => '<strong>Registrando tempo</strong>',
            'time_body' => 'O tempo gasto em um ticket é registrado em uma seção dedicada de <strong>Registros de Tempo</strong> no painel de leitura, situada entre o painel de objetos CMDB vinculados e o painel de Notas. O cabeçalho mostra o total acumulado (ex. "Total 2h 30m"), e cada entrada abaixo mostra o tempo gasto, o analista, a data e quaisquer notas que você adicionou.',
            'time_step1' => '<strong>Formulário inline</strong> &mdash; digite os minutos gastos no campo numérico, uma descrição curta opcional no campo de notas e clique em <strong>Adicionar</strong>. A nova entrada aparece imediatamente no topo da lista com seu nome e o horário atual.',
            'time_step2' => '<strong>Retroagir pelo botão direito</strong> &mdash; se precisar registrar um tempo que esqueceu de anotar antes, clique com o botão direito no ticket da lista e escolha <strong>Registrar tempo&hellip;</strong>. A janela inclui um seletor de data/hora para que você marque a entrada com o horário real em que o trabalho foi feito.',
            'time_step3' => '<strong>Excluir suas próprias entradas</strong> &mdash; um pequeno botão &times; aparece ao lado das entradas que você registrou. Clique nele (e confirme) para excluí-lo logicamente &mdash; a linha permanece no banco de dados com <code>is_active = 0</code> para auditoria, mas desaparece da lista. Você não pode excluir as entradas de outros analistas.',
            'time_tip1' => 'Os tempos são armazenados como minutos puros (45 min, 90 min, etc.) e exibidos como <code>45m</code> ou <code>1h 30m</code> na interface &mdash; granular o suficiente para correções rápidas, sem o incômodo do arredondamento de horas decimais.',
            'time_tip2' => 'Toda alteração de campo é registrada na trilha de atividades do ticket. Você sempre pode ver quem alterou o quê e quando, o que é essencial para conformidade de auditoria e transferência entre analistas.',
        ],
        'comments' => [
            'heading' => 'Comentários &amp; anexos',
            'intro' => 'A trilha de atividades é o coração de cada ticket. Ela captura cada ação realizada &mdash; comentários, alterações de campos, e-mails enviados e arquivos anexados &mdash; em uma linha do tempo cronológica que conta a história completa de uma solicitação de suporte.',
            'adding_heading' => '<strong>Adicionando comentários</strong>',
            'step1' => '<strong>Abra o ticket</strong> &mdash; clique em qualquer ticket na caixa de entrada para carregar seu painel de leitura. Role para baixo para ver a trilha de atividades completa e a caixa de comentários no rodapé.',
            'step2' => '<strong>Escreva sua nota</strong> &mdash; use o botão Adicionar Nota para abrir o editor de comentários. As notas são internas por padrão, visíveis apenas para os analistas da central de serviços.',
            'step3' => '<strong>Responda ou encaminhe por e-mail</strong> &mdash; use as ações Responder ou Encaminhar para enviar uma mensagem ao usuário final ou a terceiros. O e-mail é registrado na trilha de atividades junto com o conteúdo da mensagem enviada.',
            'subject_note' => '<strong>O assunto</strong> &mdash; Responder e Encaminhar mostram o assunto e você pode alterá-lo. Quando você encaminha um ticket a um fornecedor externo e a resposta dele acrescenta o próprio número ao assunto (por exemplo <em>#TCK89633 - FW: &hellip;</em>), use <strong>Responder</strong> ou <strong>Encaminhar</strong> <em>nessa</em> mensagem na conversa: ela parte do assunto dela, então seu acompanhamento mantém o número dele e cai no ticket dele. Cada mensagem mostra seu próprio assunto sob o remetente. A referência do ticket entre colchetes é sempre mantida &mdash; se você a retirar, ela é recolocada ao enviar, para que as respostas ainda voltem para este ticket.',
            'requester_note' => '<strong>Alterar o solicitante</strong> &mdash; <strong>Alterar solicitante</strong>, ao lado do remetente no topo do ticket, torna o ticket de outra pessoa: um colega que o registrou em nome de alguém, um erro na entrada. Isso é gravado no histórico do ticket. Quando o solicitante anterior parece ser a mesma pessoa escrevendo de outro endereço, é oferecido mesclá-los: os outros tickets dele também são movidos, e o endereço dele passa a ser um dos endereços da nova pessoa, para que o próximo e-mail dele caia ali. Uma linha <strong>Solicitante</strong> sob o remetente aparece sempre que o ticket é para alguém diferente de quem escreveu a mensagem. Um e-mail de um endereço vinculado a uma pessoa (Pessoas &rarr; a página dela &rarr; Endereços de e-mail) é dela, então nunca cria uma segunda pessoa.',
            'addresses_note' => '<strong>Endereços enquanto você digita</strong> &mdash; comece a digitar em <strong>Para</strong> ou <strong>Cc</strong> e o FreeITSM sugere endereços: primeiro o <strong>service desk</strong> de um fornecedor (defina-o no fornecedor em Contratos), depois contatos de fornecedores, pessoas da empresa do ticket e endereços para os quais se enviou e-mail recentemente a partir dos tickets dessa empresa. Use as setas e Enter, ou clique; escolha quantos quiser, ou continue digitando o seu. Um endereço dos tickets de uma empresa nunca é sugerido nos de outra, e para quem um ticket confidencial foi enviado por e-mail nunca é sugerido.',
            'attachments_note' => '<strong>Anexos de e-mail</strong> &mdash; na lista de anexos, clicar em um o abre em uma janela sobre o ticket quando o tipo de arquivo permite: imagens, PDFs, documentos do Word, planilhas e arquivos CSV, texto, áudio e vídeo, com um botão de download. Qualquer outro é baixado. <strong>Salvar em Arquivos</strong> ao lado de cada um - e ao lado de cada arquivo de uma nota - copia-o para uma pasta em Arquivos. Para colocar no ticket um arquivo que já está em Arquivos, use <strong>De Arquivos</strong> na janela <strong>Adicionar nota</strong> (<strong>Do computador</strong> é o botão ao lado) - abre uma janela como uma caixa de diálogo de arquivos, com as pastas à esquerda e seus arquivos à direita - como um link (aberto por Arquivos, sob as permissões da pasta, nunca mostrado no portal) ou uma cópia, conforme Arquivos &rarr; Configurações &rarr; Compartilhamento permitir.',
            'files_heading' => '<strong>Anexos de arquivos</strong>',
            'files_body' => 'Anexe capturas de tela, logs, documentos ou qualquer arquivo de apoio diretamente a um ticket. Os arquivos podem ser arrastados para a área de soltar anexos ou selecionados pelo navegador de arquivos. Os anexos são armazenados no servidor e vinculados à trilha de atividades do ticket, para que nada se perca.',
            'audit_heading' => '<strong>Registro de auditoria</strong>',
            'export_heading' => '<strong>Relatórios do caso</strong>',
            'export_body' => 'Para uma revisão ou um auditor, <strong>Exportar</strong> na barra de ferramentas do ticket transforma o ticket e suas tarefas em um único relatório imprimível - veja <a href="#case-reports">Relatórios do caso</a>.',
            'audit_body' => 'A trilha de atividades registra automaticamente cada ação sem intervenção do analista. Quando uma prioridade é alterada de Média para Alta, os valores antigo e novo são capturados. Quando um ticket é reatribuído, tanto o analista anterior quanto o novo são registrados. Isso cria um histórico completo e à prova de adulteração que atende aos requisitos de auditoria da ITIL e ajuda os gestores a entender como os tickets estão sendo tratados.',
            'tip' => 'Ao responder por e-mail, você pode adicionar destinatários em Cc e anexar arquivos na mesma ação. Toda a conversa por e-mail é encadeada na trilha de atividades do ticket, mantendo toda a comunicação em um só lugar.',
        ],
        'ai' => [
            'heading' => 'Ferramentas de IA',
            'intro' => 'Dois recursos com tecnologia Claude ficam dentro do fluxo de trabalho do ticket: a <strong>Limpeza de Resposta</strong> reescreve um rascunho bruto em um e-mail bem formatado, e o <strong>Perguntar à IA</strong> pesquisa a base de conhecimento em linguagem natural usando o contexto do ticket.',
            'cleanup_heading' => '<strong>Limpeza de Resposta &mdash; botão ✨ no editor de resposta</strong>',
            'cleanup_body' => 'Digite um rascunho rápido e bruto em uma resposta (ou apenas tópicos como *"precisa reiniciar o serviço de impressão, tirar captura de tela para eles"*) e clique no botão <strong>✨ Limpar</strong>. O Claude o reescreve como um e-mail bem formatado &mdash; adiciona uma saudação <em>Prezado(a) [nome],</em> a partir do solicitante, corrige a gramática, aplica o tom configurado e encerra com <em>Atenciosamente,</em>. O prompt é restrito para que ele NÃO invente detalhes técnicos, fabrique desculpas ou aumente o conteúdo além do que você escreveu.',
            'cleanup_streams' => '<strong>Transmite ao vivo</strong> &mdash; a reescrita aparece no editor conforme o Claude a gera (sem esperar diante de um indicador de carregamento).',
            'cleanup_undo' => '<strong>Link de desfazer por 30s</strong> &mdash; caso o Claude estrague a reescrita, um pequeno link <em>Desfazer</em> aparece abaixo do editor por 30 segundos após a conclusão da reescrita, restaurando o rascunho original.',
            'cleanup_tone' => '<strong>Por tom</strong> &mdash; três predefinições de tom configuráveis em <strong>Configurações &rarr; Limpeza de Resposta</strong>: <em>Amigável</em> (padrão), <em>Formal</em>, <em>Breve</em>. Escolha a que combina com o estilo da sua equipe.',
            'cleanup_key' => '<strong>Chave de API própria</strong> &mdash; chave Anthropic separada dos recursos de IA de RFP / Conhecimento / Workflow, para que seu uso apareça como uma linha própria no painel de faturamento da Anthropic. Configurada em <strong>Configurações &rarr; Limpeza de Resposta</strong>.',
            'cleanup_prompt' => '<strong>Seu próprio prompt</strong> &mdash; <em>Tickets &rarr; Configurações &rarr; Limpeza de respostas</em> mostra o prompt do sistema, e você pode alterá-lo. Cada versão salva é mantida em <em>Histórico</em>: <em>Restaurar</em> recoloca uma anterior, e <em>Redefinir</em> volta ao prompt integrado.',
            'cleanup_tip' => 'A Limpeza é mais indicada para respostas de rotina do tipo "tentei isto, por favor tente X". Para mensagens longas e cheias de nuances, é melhor escrevê-las você mesmo &mdash; a IA é ótima em estrutura, mas não conhece o seu ambiente específico.',
            'ask_heading' => '<strong>Perguntar à IA &mdash; botão 🤖 na barra de ferramentas do ticket</strong>',
            'ask_body' => 'Clique no botão <strong>Perguntar à IA</strong> (🤖) na barra de ferramentas do ticket para abrir um painel de chat deslizante que conhece o assunto, o corpo e o contexto do painel de leitura do ticket aberto. Faça perguntas como *"já vimos isso antes?"* ou *"qual é a correção habitual para este erro?"* e ele pesquisa a base de <a href="../knowledge/" style="color:#0078d4;">Conhecimento</a> de forma semântica (via Claude + embeddings da OpenAI) e responde com artigos relevantes, com links diretos para abri-los.',
            'ask_context' => '<strong>Sensível ao contexto</strong> &mdash; o painel sabe qual ticket você está vendo, então você pode fazer perguntas genéricas e ele descobre o contexto relevante.',
            'ask_linked' => '<strong>Artigos vinculados</strong> &mdash; as sugestões são clicáveis e abrem o artigo de conhecimento correspondente em uma nova aba.',
            'ask_shared' => '<strong>Compartilhado com o módulo de Conhecimento</strong> &mdash; a IA usa a mesma chave + modelo da busca por IA do Conhecimento, então configurar uma vez habilita ambos. Consulte a ajuda do módulo de Conhecimento para detalhes de configuração.',
        ],
        'csat' => [
            'heading' => 'Pesquisas de satisfação do cliente (CSAT)',
            'intro' => 'Envie por e-mail uma pesquisa de satisfação de 1&ndash;5 ao solicitante quando um ticket é resolvido, capture a resposta em uma página de destino sem login e acompanhe as tendências por analista em uma página de análise dedicada.',
            'modes_heading' => '<strong>Dois modos de disparo &mdash; escolha um</strong>',
            'mode_auto' => '<strong>Automático ao fechar</strong> &mdash; a pesquisa é enfileirada automaticamente quando um ticket passa para qualquer status fechado. O analista não precisa fazer nada &mdash; a resolução dispara a pesquisa.',
            'mode_manual' => '<strong>Apenas manual</strong> &mdash; o analista clica no botão ⭐ <strong>Feedback</strong> na barra de ferramentas do ticket quando quiser perguntar. Útil quando você prefere decidir ticket a ticket se convida ao feedback.',
            'starters_note' => '<strong>Tickets abertos por um caso de Entradas e saídas</strong> (uma etapa de modelo aberta como ticket) não recebem pesquisa automática, e seu solicitante não recebe e-mails automáticos, a menos que o modelo marque <strong>Enviar e-mail ao solicitante sobre estes tickets</strong>. Cada e-mail não enviado aparece no log de envio da caixa postal como ignorado, com o motivo. O ticket mostra a qual caso pertence em seus links.',
            'switch_note' => 'Não usa CSAT? Desative em <strong>Sistema &rarr; Módulos &rarr; Disponibilidade &rarr; Recursos de tickets</strong> e ele desaparece: sem pesquisas, sem página de CSAT, sem botão Solicitar feedback, e links de pesquisas antigas informam que o feedback não está mais sendo coletado. Nada é excluído.',
            'mode_off' => '<strong>Desligado</strong> &mdash; recurso desativado; nenhum e-mail de pesquisa é enviado.',
            'modes_choose' => 'Escolha em <strong>Tickets &rarr; Configurações &rarr; CSAT</strong>. O botão manual ainda funciona no modo <em>automático</em> &mdash; os analistas podem solicitar feedback novamente em um ticket que já foi pesquisado, se necessário.',
            'template_heading' => '<strong>O modelo de e-mail</strong>',
            'template_body' => 'O conteúdo do e-mail da pesquisa vem da aba existente <strong>Modelos de e-mail</strong> &mdash; crie um modelo com o evento <strong>Pesquisa CSAT</strong> (o novo evento ao lado de <em>Ticket atribuído</em> / <em>Ticket fechado</em>) e incorpore o código de mesclagem <code>[csat_link]</code> onde quiser que apareça a URL de avaliação. Os códigos de mesclagem padrão (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) estão disponíveis normalmente.',
            'template_tip' => 'Se não existir um modelo CSAT ativo, o botão <em>Feedback</em> recusa com um erro claro e o disparo automático é silenciosamente ignorado &mdash; você nunca pode gerar links de pesquisa inativos.',
            'survey_heading' => '<strong>A página da pesquisa</strong>',
            'survey_body' => 'O solicitante clica no link do e-mail e cai em uma página sem login com um seletor de 1&ndash;5 mais uma caixa de comentário opcional. Dois estilos visuais configuráveis em <strong>Configurações &rarr; CSAT</strong>:',
            'survey_stars' => '<strong>Estrelas</strong> &mdash; comportamento clássico de preenchimento ao passar o cursor. Passar o cursor sobre a estrela nº 3 preenche a nº 1+nº 2+nº 3 em dourado. Clique para fixar.',
            'survey_emojis' => '<strong>Emojis</strong> &mdash; 5 carinhas 😡 🙁 😐 🙂 😀 começam em tons de cinza com 40% de opacidade; a que está sob o cursor ou selecionada volta à cor cheia em escala de 1,25&times;. Clique para fixar.',
            'survey_store' => 'Ambos os modos armazenam o mesmo número de 1&ndash;5, então os painéis e as médias funcionam de forma idêntica, independentemente do estilo em uso. A URL da pesquisa é de uso único &mdash; depois que o usuário envia, o mesmo link recusa o reenvio.',
            'chat_heading' => '<strong>Perguntar aos clientes de chat no próprio chat</strong>',
            'chat_body' => 'Com <strong>Perguntar aos clientes de chat no próprio chat</strong> marcado, um cliente que escreveu pelo WhatsApp, Telegram, Slack, Microsoft Teams ou Mattermost recebe a pergunta nesse chat em vez de por e-mail &mdash; cinco botões no Telegram, Teams e Mattermost, &ldquo;responda com um único dígito&rdquo; nos demais. A resposta vai para os mesmos resultados de uma pesquisa enviada por e-mail.',
            'chat_rules' => 'O WhatsApp só recebe a pergunta enquanto a janela de resposta de 24 horas está aberta; fora dela, ou se a mensagem de chat não puder ser enviada, a pesquisa por e-mail é usada. Um dígito só conta como avaliação logo depois da pergunta &mdash; no mesmo chat, dentro de uma semana e antes de o cliente escrever qualquer outra coisa &mdash; então um &ldquo;3&rdquo; em resposta à pergunta de um analista continua sendo uma mensagem. Desativado após a atualização; ativado em uma instalação nova.',
            'analytics_heading' => '<strong>A página de análise</strong>',
            'analytics_body' => 'Clique no botão de navegação ⭐ <strong>CSAT</strong> (entre Escala e Configurações) para abrir o painel de análise em <code>tickets/csat/</code>. Período selecionável: 7 / 30 / 90 / 365 dias.',
            'card_kpi_title' => 'Blocos de KPI',
            'card_kpi_body' => 'Avaliação média (de 5), contagem de respostas, taxa de resposta (respondidas ÷ enviadas)',
            'card_dist_title' => 'Distribuição de notas',
            'card_dist_body' => 'Gráfico de barras das avaliações de 1–5 mostrando contagens e porcentagens exatas',
            'card_leader_title' => 'Ranking por analista',
            'card_leader_body' => 'Avaliação média + contagem de respostas por analista, ordenado por média decrescente. Use para conversas de desenvolvimento',
            'card_recent_title' => 'Respostas recentes',
            'card_recent_body' => 'As avaliações mais recentes primeiro, 25 por página, com os comentários em texto livre e o cliente que os deixou, com link para o ticket de origem',
            'analytics_filters' => 'Restrinja a página com os filtros abaixo do título: um intervalo de datas <strong>De / Até</strong> (em vez dos botões de dias), uma faixa de <strong>Avaliação</strong> (Positivas 4-5, Neutras 3, Negativas 1-2), um <strong>Analista</strong> e um <strong>Cliente</strong>. Analista e cliente restringem todos os números da página; a faixa de avaliação restringe apenas a lista de respostas, para que a média continue significando algo. No celular, os filtros ficam atrás do botão <strong>Filtros</strong> na parte inferior da tela. Uma página filtrada pode ser salva nos favoritos.',
            'analytics_company' => 'Todos os números seguem o <strong>seletor de empresa</strong> no cabeçalho: a empresa selecionada, ou todas as empresas que você pode ver em <strong>Todas as empresas</strong>.',
            'analytics_tip' => 'A atribuição por analista sobrevive à reatribuição do ticket porque o id do analista é capturado na linha da pesquisa no momento do envio, e não consultado ao vivo. Se um ticket for passado adiante antes de ser fechado, o analista que efetivamente o fechou é o dono da avaliação.',
            'one_heading' => '<strong>Uma pesquisa por ticket</strong>',
            'one_body' => 'Se <em>Uma pesquisa por ticket</em> estiver ativado (padrão), um ticket reaberto e fechado novamente só recebe outra pesquisa quando um analista a dispara manualmente &mdash; isso evita o envio repetido de pesquisas para um ticket instável que fica reciclando. Desative se quiser que cada fechamento dispare uma nova pesquisa.',
        ],
        'users' => [
            'heading' => 'Gerenciamento de usuários',
            'intro' => 'O botão de navegação <strong>Usuários</strong> abre <code>tickets/users.php</code> &mdash; um diretório de cada usuário final (as pessoas que abrem tickets, não os analistas) junto com o histórico de tickets de cada um.',
            'p_intro' => 'Os usuários entram no sistema de quatro formas reativas &mdash; autorregistro pelo portal, um e-mail recebido de um novo remetente, o coletor de caixa de entrada ou o mecanismo de workflow criando um a partir de um ticket disparado. Isso cobre a maioria dos casos, mas a página de Usuários também permite <strong>pré-criar</strong> um usuário (ex. um novo colaborador que está prestes a precisar de acesso) e <strong>editar</strong> ou <strong>excluir</strong> linhas existentes.',
            'add_heading' => '<strong>Adicionar usuário</strong>',
            'add_body' => 'O botão <strong>Adicionar</strong> no cabeçalho da lista de usuários abre o editor de pessoas. É o mesmo editor que <strong>Ativos &rarr; Usuários</strong> abre, então uma pessoa é adicionada e alterada do mesmo jeito em qualquer tela:',
            'add_email' => '<strong>E-mail</strong> &mdash; opcional, porque pessoas que entram por um diretório podem não ter caixa postal; elas são localizadas pelo nome de acesso. Informe um endereço de e-mail ou um nome de exibição. O endereço deve ser único e não pode pertencer a um analista.',
            'add_names' => '<strong>Nome de exibição / nome preferido</strong> &mdash; opcional. O nome preferido é como o usuário se vê sendo saudado nos e-mails (ex. <em>"Ed"</em> em vez de <em>"Ed Mozley"</em>).',
            'add_password' => '<strong>Senha</strong> &mdash; opcional. Deixá-la em branco cria uma conta <em>sem senha</em> &mdash; exatamente o mesmo estado em que começam os usuários de tickets recebidos. O usuário pode depois reivindicar a conta pelo fluxo de registro do portal de autoatendimento, definindo sua própria senha.',
            'add_details' => '<strong>Cargo, departamento, escritório, telefone, celular, ID do funcionário e gestor</strong> &mdash; todos opcionais e todos descrevem a <em>pessoa</em>, não o login. Vale preencher: o <strong>escritório</strong> diz em qual unidade alguém está antes de você ir procurá-lo, o <strong>gestor</strong> registra a linha de subordinação (digite parte de um nome para encontrá-lo) e o <strong>ID do funcionário</strong> é a chave de ligação ao conciliar com um sistema de folha de pagamento que nunca ouviu falar de endereço de e-mail. Quando você importa de um diretório, tudo isso chega preenchido. Um catálogo de endereços CardDAV preenche tudo, exceto ID do funcionário e gestor, que um cartão de contato não tem onde guardar.',
            'managed_heading' => '<strong>Pessoas mantidas em outro lugar</strong>',
            'source_body' => '<strong>De onde uma pessoa vem</strong> é indicado nos detalhes dela (<em>Detalhes de: Contoso AD - diretório</em>), e o filtro <strong>Fonte</strong> abaixo da caixa de pesquisa lista apenas as pessoas de um diretório ou catálogo de endereços, ou apenas as adicionadas no FreeITSM, com uma contagem ao lado de cada uma. Ele aparece assim que alguém é vinculado a uma fonte.',
            'add_book_body' => '<strong>Adicionar ao catálogo de endereços.</strong> Alguém que enviou um e-mail existe aqui, mas em nenhum catálogo de endereços. Se um administrador tiver ativado <em>Permitir que analistas adicionem pessoas a este catálogo de endereços</em> (Sistema &rarr; Autenticação, no catálogo de endereços), essa pessoa ganha um botão <strong>Adicionar ao catálogo de endereços</strong> ao lado de Editar. Ele pergunta primeiro, mostrando o que irá para o cartão, depois cria o contato e o vincula &mdash; a mesma pessoa, não uma cópia. Ele não adiciona alguém cujo endereço de e-mail o catálogo já tem (execute a importação em vez disso), e garante que a próxima importação capturará o novo contato, ou retira o cartão.',
            'managed_body' => 'Quando uma pessoa foi importada &mdash; do LDAP ou Active Directory, ou de um catálogo de endereços CardDAV &mdash; os detalhes que pertencem a essa fonte são <strong>somente leitura</strong> e o modal os exibe em cinza. O que quer que tenha vindo de lá é a fonte da verdade, e a próxima importação sobrescreveria qualquer coisa digitada aqui, então o salvamento é recusado de imediato, em vez de aceito e silenciosamente revertido uma hora depois. <strong>Quais</strong> detalhes depende da fonte: um diretório é dono de todos os sete, enquanto um catálogo de endereços é dono de cinco &mdash; ele não tem onde guardar um número de funcionário ou uma linha hierárquica, então esses dois continuam seus para preencher. E se o catálogo de endereços tiver <em>gravar alterações de volta</em> ativado, nenhum deles fica bloqueado: o que você digita é enviado ao cartão de contato, então não há nada para a próxima importação reverter. Tudo o mais no registro, incluindo empresa e senha, é sempre editável.',
            'edit_heading' => '<strong>Editar usuário</strong>',
            'edit_body' => 'Selecione um usuário na lista e clique em <strong>Editar</strong> no cabeçalho de detalhes. É o mesmo editor, já preenchido. Salvar sem senha deixa o hash existente intacto; informar uma a redefine. Se o gestor da pessoa for alguém de uma empresa que você não pode ver, a caixa Gestor avisa e o gestor é mantido como está, a menos que você escolha outra pessoa.',
            'signin_body' => '<strong>Entra com</strong> mostra a qual provedor de login único a pessoa está vinculada. <strong>Desvincular</strong>, ao lado, depois de uma confirmação, remove esse vínculo para que o próximo acesso comece do zero &mdash; para quem mudou de provedor ou foi vinculado à conta errada. Não é oferecido para pessoas gerenciadas por uma sincronização de diretório, que simplesmente as vincularia de novo.',
            'company_body' => '<strong>Empresa</strong> aparece quando há mais de uma. Para uma pessoa nova, deixá-la em branco define a empresa a partir do endereço de e-mail; para uma pessoa existente, em branco significa sem empresa, e os tickets dela vão para a triagem.',
            'managers_heading' => '<strong>Gestores</strong>',
            'managers_body' => 'Uma pessoa pode ser definida como <strong>gestor</strong> no portal de autoatendimento: ela ganha uma aba <strong>Tickets da equipe</strong> com os tickets das pessoas que gerencia. Fica desativado até um administrador ativar em <strong>Sistema &rarr; Gestores</strong>, onde também se decide se os gestores podem responder ou fechar esses tickets e o que veem de um ticket confidencial (nada, por padrão).',
            'managers_sources' => 'Alguém é gestor de duas maneiras, ambas ao mesmo tempo: é o <strong>Gestor</strong> nos registros de outras pessoas (manualmente ou pelo seu diretório) e tem <strong>linhas de gestão</strong> configuradas. Clique em <strong>Acesso de gestor</strong>, ao lado de Editar, para abrir uma página em tela cheia dessa pessoa, onde você pode dar a ela todos, pessoas específicas, grupos de pessoas, departamentos ou toda a sua linha de subordinação, e <strong>excluir</strong> pessoas &mdash; uma exclusão sempre prevalece, inclusive sobre o campo Gestor. A página mostra quantas pessoas ela pode ver e as lista, calculadas como se os gestores já estivessem ativados, para você conferir antes de ativar. Clique em qualquer pessoa dessa lista para ver <strong>por que</strong> o gestor pode vê-la e como impedir isso.',
            'managers_rules' => 'Um gestor só vê pessoas da própria empresa, nunca a si mesmo e nada depois de sair da empresa. Os departamentos são comparados pelo nome digitado em cada pessoa, então um departamento renomeado deixa de corresponder &mdash; a página e Sistema &rarr; Gestores avisam sobre uma linha de departamento que não corresponde a ninguém. Por padrão, somente administradores podem alterar as linhas de gestão; Sistema &rarr; Gestores pode abri-las a qualquer pessoa que possa editar pessoas.',
            'delete_heading' => '<strong>Excluir usuário</strong>',
            'delete_body' => 'O botão <strong>Excluir</strong> é <strong>seguro quanto a FK</strong>: ele recusa se o usuário for o solicitante em algum ticket ou tiver alguma linha em <code>users_assets</code>, retornando uma mensagem clara <em>"Não é possível excluir: este usuário é o solicitante em N ticket(s). Reatribua ou feche esses tickets primeiro."</em>. O histórico de auditoria nunca pode ser quebrado silenciosamente.',
            'tip' => 'Todos os campos da janela têm o preenchimento automático do navegador desativado (incluindo <code>autocomplete="new-password"</code> no campo de senha), para que as credenciais salvas do próprio analista não sejam sugeridas em um formulário cuja finalidade é criar o registro de <em>outra pessoa</em>.',
            'groups_heading' => '<strong>Grupos</strong>',
            'groups_body' => 'A aba <strong>Grupos</strong> ao lado de <strong>Pessoas</strong> reúne grupos nomeados de pessoas &mdash; analistas e usuários do portal de autoatendimento juntos no mesmo grupo. Um grupo é criado uma vez aqui e depois usado em todo o FreeITSM, para que você possa dar a ele acesso a uma pasta de conhecimento ou atribuir um curso de treinamento sem montar a mesma lista duas vezes.',
            'groups_make' => '<strong>Crie um</strong> com <strong>Adicionar</strong> na aba Grupos: um nome, e uma descrição que vale a pena preencher, porque a próxima pessoa precisa conseguir saber para que o grupo serve.',
            'groups_add' => '<strong>Adicione pessoas</strong> pesquisando por elas &mdash; a busca encontra analistas e usuários do portal juntos, então você não precisa saber de qual tipo alguém é.',
            'groups_expiry' => '<strong>Dê a uma associação uma data de término</strong> quando o acesso for temporário. Três engenheiros em campo por quinze dias entram com um último dia e saem do grupo sozinhos quando ele passa. Uma associação expirada permanece na lista, marcada como expirada, para que você ainda possa ver quem teve acesso e até quando.',
            'groups_uses' => '<strong>Para que um grupo serve:</strong> conceder acesso a uma pasta de conhecimento e atribuir treinamento do LMS a um conjunto de pessoas de uma vez. As alterações de associação entram em vigor imediatamente &mdash; não há nada para reaplicar depois.',
            'groups_admin' => '<strong>Qualquer pessoa com o módulo Tickets pode ver os grupos; só um administrador pode alterar um.</strong> Adicionar alguém a um grupo também pode dar a essa pessoa acesso a uma pasta de conhecimento restrita, então é uma concessão de acesso, não uma simples organização.',
        ],
        'dash' => [
            'heading' => 'Painel',
            'intro' => 'O painel de tickets oferece análises de relance com widgets Chart.js personalizáveis. Cada analista tem seu próprio layout de painel, para que você possa se concentrar nas métricas que importam para o seu papel &mdash; seja carga de trabalho pessoal, produtividade da equipe ou conformidade com SLA.',
            'step1' => '<strong>Abra a Biblioteca</strong> &mdash; clique em Editar Painel para entrar no modo de edição e, em seguida, navegue pela biblioteca de widgets. Escolha entre widgets prontos ou crie o seu selecionando um tipo de gráfico e a propriedade de dados a agregar.',
            'step2' => '<strong>Adicione widgets</strong> &mdash; clique no botão + em qualquer widget da biblioteca para adicioná-lo ao seu painel. Ele aparece imediatamente e começa a exibir dados ao vivo do seu banco de dados de tickets.',
            'step3' => '<strong>Configure</strong> &mdash; clique no ícone de engrenagem em qualquer widget para personalizar seu título, tipo de gráfico (barras, pizza, rosca, linha, barras empilhadas, multilinha), filtro de período, filtro de departamento e agrupamento de tempo (diário, semanal, mensal).',
            'step4' => '<strong>Organize</strong> &mdash; arraste e solte os widgets para reordená-los. Seu layout é salvo por analista, portanto persiste entre as sessões.',
            'examples' => 'Exemplos comuns de widgets incluem: <strong>Tickets por Status</strong> (gráfico de rosca mostrando abertos vs resolvidos vs fechados), <strong>Tickets por Prioridade</strong> (gráfico de barras de volume por severidade), <strong>Volume Semanal</strong> (gráfico de linha acompanhando novos tickets ao longo do tempo) e <strong>Carga de Trabalho do Analista</strong> (barras empilhadas mostrando os tickets ativos de cada analista).',
            'tip' => 'Use filtros de período em widgets individuais para comparar o desempenho atual com períodos anteriores. Por exemplo, uma visão "Este Mês vs Mês Passado" ajuda você a detectar tendências no volume de tickets cedo.',
        ],
        'cal_rota' => [
            'switch_note' => 'Não usa a escala de plantão? Desative em <strong>Sistema &rarr; Módulos &rarr; Disponibilidade &rarr; Recursos de tickets</strong> - a página, suas configurações e o <em>quem está de plantão</em> do bot do War Room somem, e nada é excluído.',
            'heading' => 'Calendário &amp; escala',
            'intro' => 'Duas ferramentas de agendamento ajudam sua equipe a se manter organizada: um calendário de tickets que visualiza a carga de trabalho ao longo do tempo e uma escala de pessoal para gerenciar turnos e disponibilidade de plantão.',
            'cal_heading' => '<strong>Visualização de calendário</strong>',
            'cal_body' => 'O calendário plota cada ticket que tem um <code>work_start_datetime</code> definido (pela janela de <em>Registrar tempo</em> / <em>Agendar</em> do botão direito) como um bloco colorido em seu horário agendado. Blocos vermelhos são prioridade <em>Alta</em>, verdes são <em>Baixa</em>, azul é qualquer outra coisa. Use <em>Hoje</em>, as setas <em>&lt;</em> / <em>&gt;</em> e o botão de alternância <strong>Mês / Semana / Dia</strong> à direita do cabeçalho para navegar &mdash; <em>Anterior</em> / <em>Próximo</em> avançam por mês, semana ou dia, dependendo da visualização ativa.',
            'cal_scope' => '<strong>Meus ou Todos.</strong> O calendário abre no seu próprio trabalho agendado, com uma alternância <strong>Todos</strong> ao lado dos botões de exibição; sua escolha é lembrada. Em Todos, cada ticket recebe uma <strong>cor para quem é o responsável por ele</strong>, com uma legenda nomeando as pessoas que realmente aparecem na tela, e passar o mouse sobre um ticket diz de quem ele é sem tirar os olhos da tela. Nada fica escondido de ninguém &mdash; são os mesmos tickets que a caixa de entrada já lista.',
            'cal_edit' => '<strong>Reorganizando o trabalho.</strong> <strong>Arraste um ticket</strong> para um dia ou horário diferente: na exibição Mês ele mantém o horário, e nas exibições Semana e Dia ele assume o horário onde você o soltar, ajustado ao quarto de hora mais próximo. A duração nunca muda &mdash; arrastar diz <em>comece então</em>, não <em>torne mais longo</em>. Ou <strong>clique em um ticket</strong> para abri-lo, onde você pode alterar a data, o horário, a duração e a opção de dia inteiro, ou limpar o agendamento por completo. O calendário também <strong>se atualiza sozinho a cada poucos segundos</strong>, para que algo agendado por um colega apareça sem que você recarregue a página &mdash; e ele aguarda enquanto você tem um ticket aberto ou está no meio de um arraste.',
            'cal_month' => '<strong>Visão de mês</strong> &mdash; a clássica grade de 6 linhas com uma faixa de cabeçalho de dias da semana; cada célula de dia mostra até três pílulas de ticket com seu horário de início, mais um link <em>+N mais</em> que leva você à visão de Dia para aquela data. O dia atual é destacado.',
            'cal_week' => '<strong>Visão de semana</strong> &mdash; Seg&ndash;Dom no topo sobre uma linha do tempo vertical de 24 horas. Os tickets são exibidos como blocos coloridos de 1 hora em seu horário de início. A coluna do dia atual é destacada; o cabeçalho dos dias da semana permanece fixo enquanto a grade de horas rola.',
            'cal_day' => '<strong>Visão de dia</strong> &mdash; uma única coluna alta para o dia escolhido com a mesma linha do tempo de 24 horas. Os tickets são exibidos como blocos maiores mostrando <code>ticket_number &mdash; assunto</code> e o horário de início; clique em um para abrir seus detalhes.',
            'rota_heading' => '<strong>Escala de pessoal</strong>',
            'rota_body' => 'A página de escala permite que líderes de equipe e gestores agendem os turnos dos analistas ao longo da semana. Defina o horário de trabalho padrão, atribua períodos de plantão e marque feriados ou ausências para que a equipe sempre saiba quem está disponível.',
            'rota_step1' => '<strong>Veja a grade da escala</strong> &mdash; a escala exibe os analistas em um eixo e os dias no outro, com blocos de turno mostrando a cobertura de relance.',
            'rota_step2' => '<strong>Adicione ou edite turnos</strong> &mdash; clique em uma célula para atribuir um tipo de turno (ex. Manhã, Tarde, Noite, Plantão). As alterações são salvas imediatamente.',
            'rota_step3' => '<strong>Planeje com antecedência</strong> &mdash; navegue adiante por semana para montar a escala antecipadamente. Isso garante cobertura adequada durante períodos de pico conhecidos, feriados ou dias de treinamento.',
            'rota_step4' => '<strong>Preencha várias células de uma vez</strong> &mdash; <strong>clique com o botão direito</strong> em uma célula e escolha <em>Copiar</em> para pegar o turno nela, depois clique com o botão direito em outra e <em>Colar</em>. Para mais de uma célula, <strong>arraste sobre um bloco</strong> delas (ou ctrl-clique nas células uma a uma) e cole em todas elas. Passar o mouse sobre um <strong>cabeçalho de dia</strong> destaca aquele dia inteiro, e passar o mouse sobre o <strong>nome de um analista</strong> destaca a semana inteira dele &mdash; clique com o botão direito em qualquer um dos dois e cole em tudo. Quando algumas das células já têm um turno, o menu oferece as duas opções em palavras simples &mdash; <em>Colar em todas as 7</em> e <em>Colar em 6 células vazias</em> &mdash; para que você escolha antes de confirmar, não depois. Substituir pede confirmação e informa quantos turnos serão substituídos; preencher as lacunas simplesmente acontece, já que nada se perde. Os mesmos menus também <strong>limpam</strong> um dia, uma semana ou uma seleção, novamente informando antes quantos turnos isso remove.',
            'rota_step5' => '<strong>Copie um dia inteiro ou uma semana inteira de uma pessoa</strong> &mdash; clique com o botão direito em um <strong>cabeçalho de dia</strong> e escolha <em>Copiar</em> para levar todos os turnos daquele dia, ou no <strong>nome de um analista</strong> para levar a semana inteira dele. Colar em outro dia, ou outro analista, faz com que fique igual: os turnos que a cópia não tinha são limpos, então você obtém o dia que copiou, e não uma mistura dos dois. Um dia só pode ser colado em outro dia, e um analista só em outro analista &mdash; um dia é um turno <em>por pessoa</em> e uma semana é um turno <em>por dia</em>, então não há uma forma sensata de sobrepor um ao outro. Tente e o menu avisa, e diz para onde pode ir em vez disso.',
            'rota_step6' => '<strong>Copie uma semana inteira</strong> &mdash; <strong>Copiar semana</strong> e <strong>Colar semana</strong> no canto superior direito levam todos os turnos da semana que você está vendo e os soltam em outra, o jeito mais rápido de montar uma escala repetida. Colar <em>substitui</em> a semana de destino, então a confirmação informa quantas entradas estão prestes a ser removidas. Isso só afeta os dias e as pessoas que a grade está realmente mostrando.',
            'tip' => 'Combine o calendário e a escala para um planejamento de capacidade eficaz. Se o calendário mostra um pico de tickets toda segunda-feira de manhã, garanta que a escala tenha cobertura extra agendada para esse horário.',
        ],
        'settings' => [
            'heading' => 'Configurações',
            'intro' => 'A página de Configurações é onde você configura os componentes básicos do seu sistema de tickets. Todos os valores de listas, metas de SLA, integração de e-mail e campos personalizados são gerenciados aqui.',
            'sla_callout_title' => 'Gerenciamento de SLA &mdash; guia completo',
            'sla_callout_body' => 'Opções configuráveis, calendários comerciais, status de pausa, notificações de violação, configuração do cron, além de exemplos práticos para equipes em um único fuso horário e entre fusos horários. Substancial o suficiente para merecer sua própria página.',
            'card_dept_title' => 'Departamentos',
            'card_dept_body' => 'Crie departamentos como TI, RH e Financeiro. Cada departamento se torna uma pasta na caixa de entrada e um filtro no painel',
            'card_types_title' => 'Tipos de ticket',
            'card_types_body' => 'Defina os tipos de solicitação que sua central atende: Incidente, Solicitação de Serviço, Problema, Mudança. Os tipos ajudam os analistas a classificar o trabalho',
            'card_type_rules_title' => 'Tipo para novos tickets',
            'card_type_rules_body' => 'Em Tipos de ticket, dê a todo novo ticket um tipo quando ninguém escolher um: um padrão e regras antes dele - pela forma como chegou (e-mail, portal, chat web, telefone, monitoramento...), caixa postal, origem, departamento, palavras no assunto ou o domínio do solicitante. A primeira regra que corresponder vence; Testar mostra qual tipo um ticket receberia',
            'card_priorities_title' => 'Prioridades',
            'card_priorities_body' => 'Defina níveis de prioridade com nomes, cores e ordens de exibição. Cada prioridade se vincula a uma meta de SLA para resposta e resolução',
            'card_statuses_title' => 'Status',
            'card_statuses_body' => 'Personalize as etapas do ciclo de vida do ticket. Os status padrão incluem Novo, Aberto, Em Andamento, Pendente, Resolvido e Fechado',
            'card_categories_title' => 'Categorias',
            'card_categories_body' => 'Agrupe os tickets por área técnica: Hardware, Software, Rede, Acesso. As categorias alimentam as divisões nos relatórios',
            'card_sla_title' => 'Metas de SLA',
            'card_sla_body' => 'Defina metas de tempo de resposta e resolução por prioridade. Os cronômetros de SLA aparecem nos tickets e orientam os avisos de violação',
            'card_email_title' => 'Importação de e-mail',
            'card_email_body' => 'Conecte uma caixa de entrada (Exchange, Microsoft 365) para importar e-mails automaticamente como novos tickets. As respostas se encadeiam de volta aos tickets existentes',
            'card_custom_title' => 'Campos personalizados',
            'card_custom_body' => 'Adicione seus próprios campos aos tickets para dados que sua organização precisa capturar e que não são cobertos pelo conjunto de campos padrão',
            'card_templates_title' => 'Modelos de e-mail',
            'card_templates_body' => 'Configure os modelos de notificação enviados aos usuários finais quando os tickets são criados, atualizados, resolvidos ou para a pesquisa CSAT. Incorpore códigos de mesclagem como [requester_name] e [csat_link]',
            'card_checklists_title' => 'Checklists',
            'card_checklists_body' => 'Decide o que acontece quando alguém fecha um ticket que ainda tem etapas obrigatórias da lista de verificação pendentes: <strong>avisar</strong> e registrar uma nota interna nomeando as etapas e quem fechou o ticket, ou <strong>bloquear</strong> o fechamento até que sejam concluídas. Aplicado em qualquer lugar onde um ticket possa ser fechado - incluindo ações em massa, a API REST e a automação de workflow',
            'card_custom_fields_title' => 'Campos personalizados',
            'card_custom_fields_body' => 'Crie os detalhes extras de que um tipo de ticket precisa - texto, número, data, sim / não, uma lista suspensa com suas próprias opções, um endereço web ou de e-mail - e vincule cada um a alguns tipos de ticket ou a todos. Cada campo define se deve ser preenchido <strong>quando o ticket é registrado</strong> (o formulário Novo ticket, a API REST e, se solicitado, o portal), <strong>antes de ser fechado</strong> (conforme a regra de Campos obrigatórios) ou ambos, e se o <strong>solicitante é questionado</strong> sobre ele no portal - onde aparece um seletor de tipo de ticket quando ele muda o que é perguntado. As respostas aparecem no painel de propriedades do ticket e no seu histórico. Mudar o tipo de um ticket oculta as respostas que o novo tipo não tem, e nunca as exclui',
            'card_mandatory_title' => 'Campos obrigatórios',
            'card_mandatory_body' => 'Marque os campos que devem ser preenchidos antes que um ticket possa ser fechado - categoria, código de resolução, responsável e assim por diante. Depois escolha o que acontece quando alguém fecha um com um campo vazio: <strong>avisar</strong>, <strong>avisar e enviar e-mail</strong> para alguém como um gerente de entrega de serviços, ou <strong>recusar</strong> o fechamento. Uma opção separada registra isso no ticket como uma nota interna. Um campo desativado para uma empresa nunca é obrigatório, e mesclar tickets nunca o aciona. Aplicado em todos os lugares onde um ticket pode ser fechado - ações em massa, a API REST e a automação de fluxo de trabalho inclusas',
            'card_cleanup_title' => 'IA de Limpeza de Resposta',
            'card_cleanup_body' => 'Chave Anthropic + modelo + tom para o botão ✨ Limpar no editor de resposta. Chave separada de outros recursos de IA para faturamento granular',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'Modo de envio (desligado / automático / manual), atraso, proteção de uma por ticket, escala (estrelas ou emojis). Consulte a seção 6 para o fluxo completo',
            'email_heading' => '<strong>Importação de e-mail em detalhe</strong>',
            'email_body' => 'O recurso de importação de e-mail conecta-se à sua caixa de entrada compartilhada e traz novas mensagens como tickets. Quando um usuário final envia um e-mail para seu endereço de suporte (ex. support@suaempresa.com), o FreeITSM cria um ticket com o assunto do e-mail como título e o corpo do e-mail como descrição. Se o remetente responder a um e-mail de notificação, a resposta é encadeada no ticket existente em vez de criar uma duplicata.',
            'email_step1' => '<strong>Configure a caixa de entrada</strong> &mdash; vá em Configurações e insira suas credenciais do Exchange ou Microsoft 365. A autenticação OAuth é suportada para conexões seguras e sem senha.',
            'email_step2' => '<strong>Defina o intervalo de coleta</strong> &mdash; escolha com que frequência o FreeITSM verifica novas mensagens na caixa de entrada. Intervalos mais curtos significam criação de tickets mais rápida.',
            'email_step3' => '<strong>Mapeie os padrões</strong> &mdash; defina o departamento, o tipo e a prioridade padrão para tickets criados a partir de e-mails. Os analistas podem ajustá-los após a importação.',
            'email_thread_note' => '<strong>Uma resposta sem número de ticket</strong> &mdash; todo e-mail que o FreeITSM envia leva o número do ticket, então uma resposta a ele sempre encontra seu ticket. Quando alguém responde ao seu <em>próprio</em> primeiro e-mail (para acrescentar um anexo esquecido, por exemplo), não há número para encontrar, e por padrão essa resposta abre um novo ticket. Defina Tickets &rarr; Configurações &rarr; Geral &rarr; <strong>Uma resposta sem número de ticket</strong> como <strong>Entra no ticket a que sua conversa pertence</strong> e ela vai para o ticket que esse primeiro e-mail abriu, reabrindo-o se estava fechado (quando a reabertura está ativada). Só e-mails na mesma caixa postal são correspondidos.',
            'email_reply_to_note' => '<strong>Quem Responder atende</strong> &mdash; por padrão, a caixa Responder é endereçada à pessoa da mensagem que você está lendo. Se colegas do solicitante entram na conversa e você prefere sempre responder ao solicitante, defina Tickets &rarr; Configurações &rarr; Geral &rarr; <strong>A resposta vai para</strong> como <strong>O solicitante do ticket</strong>. Você sempre pode alterar o endereço antes de enviar.',
            'email_sent_copy_note' => '<strong>Uma cópia do e-mail enviado na pasta Enviados (IMAP básico)</strong> - uma caixa postal IMAP básica envia por SMTP, que não guarda cópia, então quem lê a mesma caixa no Thunderbird ou no webmail não veria o que o service desk enviou. Edite a caixa postal e ative <strong>Salvar uma cópia dos e-mails enviados</strong>, logo abaixo de <em>Usar o login IMAP para envio</em>: toda resposta, e-mail de modelo, e-mail de workflow e e-mail do sistema que ela envia também é colocado na pasta Enviados, marcado como lido. Notificações internas para analistas nunca são arquivadas. Deixe <strong>Pasta Enviados</strong> em branco para usar a pasta que seu servidor de e-mail marca como Enviados, ou digite o nome dela. Deixe o interruptor desativado se seu servidor de e-mail já arquiva os e-mails enviados (Gmail e Microsoft 365 arquivam, e algumas empresas de hospedagem também) - você teria duas cópias. <strong>Testar</strong> informa em qual pasta a cópia foi parar. Se uma cópia não puder ser salva, o e-mail foi enviado mesmo assim, e o motivo aparece na aba <strong>Atividade</strong> &rarr; <strong>Saída</strong> da caixa postal como <em>Cópia para a pasta Enviados</em>.',
            'tip' => 'Use modelos de e-mail para manter um tom profissional e consistente em todas as comunicações com os usuários finais. Os modelos suportam espaços reservados dinâmicos para referência do ticket, nome do solicitante, nome do analista e status.',
            'closemsg_heading' => '<strong>Uma mensagem única ao fechar um ticket</strong>',
            'closemsg_body' => 'Coloque <code>[ticket_closed_message]</code> em qualquer lugar de um modelo <strong>Ticket fechado</strong> ativo e, a partir daí, definir um ticket como um status fechado pede ao analista uma frase - <em>&ldquo;o carregador reserva está na sua mesa&rdquo;</em>, <em>&ldquo;fechando conforme combinado por telefone&rdquo;</em>. O que quer que a pessoa digite cai exatamente onde você colocou o espaço reservado, então você mantém o controle do texto ao redor. Não é uma configuração e nada armazena isso: uma nota, um ticket, um e-mail. Não digite nada e a linha simplesmente não aparece - sem espaço em branco, sem pontuação solta.',
            'closemsg_note' => '<strong>A pergunta só aparece quando o espaço reservado está realmente no modelo.</strong> Sem ele, qualquer coisa que um analista digitasse seria descartada silenciosamente, e toda equipe que não quiser isso ganharia um clique extra a cada fechamento. Então ela se ativa sozinha quando você configura e fica fora do caminho quando você não configura.',
            'cat_heading' => '<strong>Categorias, e os dois campos ao lado delas</strong>',
            'cat_body' => 'O <em>tipo</em> de um ticket diz que tipo de coisa é; a <em>categoria</em> diz sobre o que é. Monte a lista em <strong>Configurações &rarr; Categorias</strong>, junto com as opções que decidem se qualquer uma delas aparece no ticket.',
            'cat_card_one_title' => 'Categoria',
            'cat_card_one_body' => 'O que o ticket foi relatado como, escolhido quando ele é aberto. Um ticket carrega exatamente uma, então um relatório das suas categorias sempre soma o número de tickets que você realmente teve.',
            'cat_card_close_title' => 'Categoria no fechamento',
            'cat_card_close_body' => 'A mesma lista perguntada de novo quando o ticket termina. Normalmente o analista apenas a confirma &mdash; ela justifica seu lugar nos casos em que o primeiro palpite estava errado, e é assim que você descobre que doze dos seus trinta e sete "problemas de impressora" eram na verdade a rede.',
            'cat_card_res_title' => 'Código de resolução',
            'cat_card_res_body' => 'Como o ticket terminou, e não sobre o que era &mdash; "Corrigido remotamente", "Treinamento realizado", "Nenhuma falha encontrada". Dez opções sensatas já vêm desde o início e você pode alterar todas.',
            'cat_rule_off' => '<strong>Os três começam desativados.</strong> Monte sua lista primeiro, depois ative os que você quiser. Cada um pode ser configurado de forma diferente para cada empresa.',
            'cat_rule_levels' => 'Categorias podem ter subcategorias com até três níveis de profundidade, e nenhum nível é obrigatório.',
            'cat_rule_type' => 'Uma categoria pode estar vinculada a um tipo de ticket, então "Integração de usuário" só é oferecida em uma solicitação de serviço. O vínculo pertence à categoria de nível superior e suas subcategorias o seguem.',
            'cat_rule_typechange' => '<strong>Alterar o tipo de um ticket limpa uma categoria que pertencia ao tipo antigo</strong>, e isso é informado na tela. Uma categoria não vinculada a nenhum tipo sobrevive à alteração.',
            'cat_rule_portal' => 'Marque <em>Clientes podem escolher isto</em> para oferecer uma categoria no portal de autoatendimento. Solicitantes veem uma lista curta em linguagem simples, enquanto analistas veem a árvore inteira.',
            'cat_rule_retire' => 'Desative uma categoria para aposentá-la &mdash; ela permanece nos tickets que já a têm e para de ser oferecida em novos. Isso quase sempre é melhor do que excluir, o que é recusado enquanto algo ainda a usa.',
            'cat_rule_report' => 'Os três podem ser exibidos em gráfico no painel de tickets. Os dois gráficos de categoria são consolidados até o nível superior, e tickets sem nada definido são contados como <em>Não categorizado</em> em vez de ocultados.',
            'cat_rule_workflow' => '<strong>Categorias em workflows:</strong> um workflow pode direcionar tickets por categoria - uma condição <em>Categoria</em> funciona em todo gatilho de ticket, e o gatilho <em>A categoria de um ticket muda</em> pega um ticket categorizado na triagem. Por padrão, uma condição que nomeia uma categoria também corresponde às suas subcategorias, então "Hardware" pega "Hardware &rarr; Laptop"; escolha <strong>Corresponde somente a essa categoria</strong> em <strong>Tickets &rarr; Configurações &rarr; Categorias &rarr; Categorias em workflows</strong> para que cada workflow nomeie cada subcategoria que quiser. Quando alterar o tipo de um ticket limpa sua categoria, o gatilho também é disparado.',
            'cat_tip' => 'Se você não tiver certeza de por onde começar, deixe as categorias vazias e ative apenas o <strong>Código de resolução</strong>. É o campo que mais rapidamente muda o que você faz &mdash; um quinto dos seus tickets voltando como "Treinamento realizado" é um problema de documentação, não de TI.',
        ],
        'tips' => [
            'heading' => 'Dicas rápidas',
            'search_title' => 'Pesquise tudo',
            'search_body' => 'A janela de pesquisa verifica referências de tickets, assuntos, nomes de solicitantes e endereços de e-mail. Use-a para encontrar tickets relacionados rapidamente quando um usuário ligar sobre um problema existente.',
            'sla_title' => 'Fique de olho nos seus SLAs',
            'sla_body' => 'Os cronômetros de SLA ficam visíveis em cada ticket no painel de leitura. Indicadores codificados por cor ficam âmbar quando uma violação se aproxima e vermelhos quando a meta foi perdida, para que você priorize de acordo.',
            'reply_title' => 'Responda pela caixa de entrada',
            'reply_body' => 'Você não precisa abrir seu cliente de e-mail para responder a um usuário final. Use o botão Responder no painel de leitura para enviar uma mensagem diretamente. Ela se encadeia ao ticket automaticamente.',
            'reply_to_title' => 'Para quem Responder vai',
            'reply_to_body' => 'Responder é endereçado à pessoa da mensagem que você está lendo. Se preferir que sempre vá para o solicitante do ticket, altere <strong>A resposta vai para</strong> em Tickets &rarr; Configurações &rarr; Geral. De qualquer forma, você pode alterar o endereço, ou adicionar pessoas em Cc, antes de enviar.',
            'trail_title' => 'Use a trilha de atividades',
            'trail_body' => 'Antes de trabalhar em um ticket, percorra sua trilha de atividades. Notas anteriores de analistas, e-mails e alterações de campos fornecem o contexto completo, para que você não peça ao usuário para repetir informações.',
            'dash_title' => 'Painel para gestores',
            'dash_body' => 'Monte um painel com widgets para taxas de conformidade de SLA, tempo médio de resolução e tickets por departamento. Compartilhe-o nas reuniões de equipe para impulsionar a melhoria contínua.',
            'rota_title' => 'Planeje com a escala',
            'rota_body' => 'Preencha a escala com pelo menos duas semanas de antecedência. Quando combinada com a visualização de calendário, ela ajuda a identificar lacunas na cobertura antes que se tornem um problema para os tempos de resposta.',
            'drag_title' => 'Arraste para triar',
            'drag_body' => 'Arraste tickets da lista até as pastas para atualizá-los sem abri-los. Subpastas de Departamento + status atualizam ambos de uma vez. A expansão automática torna os status aninhados acessíveis durante o arraste.',
            'dbl_title' => 'Clique duplo para tela cheia',
            'dbl_body' => 'Um clique único pré-visualiza um ticket no painel de leitura; o clique duplo o abre em modo de tela cheia para trabalho concentrado. Clique no ícone de maximizar ao lado do assunto para voltar.',
            'rightclick_title' => 'Clique com o botão direito para ações rápidas',
            'rightclick_body' => 'Clique com o botão direito em qualquer ticket para alterar status, prioridade ou responsável com um clique, além de vincular CMDB e registrar tempo, tudo sem sair do ticket que você está lendo no momento.',
            'ai_title' => 'Deixe a IA limpar sua resposta',
            'ai_body' => 'Digite um rascunho bruto (ou apenas tópicos) e clique em <strong>✨ Limpar</strong> &mdash; o Claude o reescreve como um e-mail adequado com saudação, correções gramaticais e despedida. Um link de desfazer aparece por 30 segundos.',
            'feedback_title' => 'Peça feedback',
            'feedback_body' => 'Ative o CSAT em <strong>Configurações &rarr; CSAT</strong> para pesquisar automaticamente os solicitantes quando seus tickets forem fechados. As tendências por analista ficam em <code>tickets/csat/</code> &mdash; ouro para conversas de desenvolvimento.',
            'precreate_title' => 'Pré-crie usuários finais',
            'precreate_body' => 'O botão de navegação <strong>Usuários</strong> permite adicionar um usuário antes de ele precisar abrir um ticket &mdash; deixe a senha em branco e ele poderá reivindicar a conta sozinho pelo portal de autoatendimento.',
        ],
        'companies' => [
            'heading' => 'Empresas &amp; roteamento de e-mail',
            'intro' => 'Quando sua instalação atende mais de uma empresa (por exemplo, um provedor de TI que dá suporte a vários clientes), os tickets de cada empresa são mantidos separados. Esta seção explica como o e-mail recebido encontra a empresa certa.',
            'switcher_body' => 'Um <strong>seletor de empresa</strong> aparece no cabeçalho. Ele define a empresa em que você está trabalhando &mdash; a lista de tickets, as pastas e as contagens mostram apenas aquela empresa, e qualquer ticket que você criar é arquivado nela. A equipe com acesso a várias empresas pode alternar entre elas; a atual é sempre exibida, para que você não responda no contexto errado. Gerencie as próprias empresas em <strong>Sistema &rarr; Empresas</strong>.',
            'switcher_remember' => 'Para iniciar cada login na empresa que você escolheu por último (ou em <strong>Todas as empresas</strong>) em vez da empresa Padrão, ative <strong>Começar na empresa que usei por último</strong> em <strong>Preferências</strong> (o menu da sua conta).',
            'mailboxes_heading' => 'Toda caixa de entrada é de um de dois tipos &mdash; é isso que decide o roteamento:',
            'card_pinned_title' => 'Caixa de entrada fixada',
            'card_pinned_body' => 'Dedicada a uma única empresa (ex. o <code>itsupport@</code> próprio de um cliente). <strong>Todos</strong> os seus e-mails são arquivados nessa empresa &mdash; o remetente é ignorado &mdash; e as respostas saem dela, para que o cliente veja sua própria central de ajuda de ponta a ponta.',
            'card_shared_title' => 'Caixa de entrada compartilhada',
            'card_shared_body' => 'Um endereço atendendo muitas empresas (ex. o único <code>support@oprovedor.com</code> de um provedor). Ele não pode saber a empresa só pelo endereço, então a descobre a partir de <strong>quem enviou o e-mail</strong>. A configuração recomendada para um provedor com muitos clientes.',
            'routing_heading' => 'Como uma caixa de entrada compartilhada escolhe a empresa',
            'routing_body' => 'Para cada e-mail recebido, ele tenta estas regras em ordem, e a primeira correspondência vence:',
            'flow_reply' => 'Resposta a um ticket',
            'flow_sender' => 'Remetente conhecido',
            'flow_domain' => 'Domínio conhecido',
            'flow_triage' => 'Triagem',
            'rule_reply' => '<strong>1. Resposta a um ticket existente</strong> &mdash; reconhecida pela sua referência, o e-mail se junta a esse ticket e mantém sua empresa.',
            'rule_sender' => '<strong>2. Um endereço de remetente específico</strong> mapeado para uma empresa (ex. <code>jane@gmail.com</code> &rarr; Acme) &mdash; essa empresa. Verificado antes do domínio, então funciona mesmo para endereços pessoais/webmail.',
            'rule_domain' => '<strong>3. O domínio do remetente</strong> mapeado para uma empresa (ex. qualquer um <code>@acme.com</code> &rarr; Acme) &mdash; essa empresa.',
            'rule_triage' => '<strong>4. Nenhuma correspondência</strong> &mdash; o e-mail vai para a fila de <strong>triagem</strong> em vez de ser perdido (veja abaixo).',
            'keys_heading' => 'Domínios &amp; remetentes específicos (definidos por empresa em Sistema &rarr; Empresas)',
            'keys_body' => 'Estas são as chaves nas quais uma caixa de entrada compartilhada faz correspondência. Cada empresa lista os domínios de e-mail que possui e, opcionalmente, endereços de remetentes individuais.',
            'card_domains_title' => 'Domínios de e-mail',
            'card_domains_body' => 'Os domínios que uma empresa possui (acme.com, acme.co.uk). Qualquer remetente em um domínio registrado é encaminhado para essa empresa. Um domínio pertence a apenas uma empresa.',
            'card_senders_title' => 'Remetentes específicos',
            'card_senders_body' => 'Endereços individuais mapeados para uma empresa, verificados antes do domínio. Use-o para um freelancer ou cliente pequeno que envia e-mails de um endereço pessoal.',
            'card_public_title' => 'Provedores públicos',
            'card_public_body' => 'Gmail, Outlook, Yahoo e similares não podem ser mapeados como domínio (muitas pessoas sem relação os compartilham) &mdash; em vez disso, mapeie o endereço exato como um remetente específico.',
            'triage_heading' => 'A fila de triagem &mdash; a rede de segurança',
            'triage_body' => 'Quando um e-mail de entrada compartilhada não corresponde a nenhuma empresa, ele cai na <strong>Triagem</strong> (acessada pelo seletor de empresa, com uma contagem ao vivo) em vez de ser perdido. Cada item mostra o remetente, o domínio, o assunto e em qual caixa de entrada ele chegou. Arquive-o em uma empresa em uma única etapa:',
            'triage_create' => 'Escolha uma empresa existente ou crie uma nova na hora.',
            'triage_assign' => 'Para um domínio normal, opcionalmente <strong>encaminhe esse domínio</strong> para a empresa; para um endereço público/webmail, opcionalmente <strong>sempre arquive esse remetente</strong> ali.',
            'triage_sweep' => 'Qualquer das escolhas <em>varre</em>: ela move também todos os outros e-mails na fila daquele domínio ou endereço e encaminha os e-mails futuros automaticamente &mdash; então você só classifica um determinado remetente uma vez.',
            'triage_tip' => 'Nada é jamais perdido. E-mails sem correspondência aguardam na triagem até alguém arquivá-los; um ticket não arquivado ainda aparece sob a empresa padrão nesse meio-tempo.',
            'test_heading' => 'Teste seu roteamento antes de entrar no ar',
            'test_body' => 'Em <strong>Sistema &rarr; Teste de roteamento de e-mail</strong>, você pode simular que um e-mail chegou &mdash; escolha uma caixa de entrada, digite um endereço de remetente &mdash; e ver exatamente em qual empresa o novo ticket cairia (ou que iria para a triagem) e qual regra decidiu isso. Ele não cria nada; apenas lê suas configurações.',
            'settings_heading' => 'Configurações: compartilhadas por padrão, personalizadas onde importa',
            'settings_body' => 'Algumas dessas Configurações podem ser <strong>personalizadas por empresa</strong>; outras permanecem compartilhadas de propósito. Quando uma configuração é uma simples lista de opções &mdash; como <strong>tipos de ticket</strong> e <strong>origens</strong> &mdash; entre no contexto de uma empresa e você verá os padrões compartilhados (cada um com um ícone de olho para ocultar os que ela não usa) mais quaisquer que ela tenha adicionado só para si. Você não pode ocultar ou excluir uma opção enquanto tickets abertos ainda a usam, e os próprios padrões compartilhados são editados a partir da empresa MSP / padrão.',
            'settings_custom_title' => 'Personalizado por empresa',
            'settings_custom_body' => 'Tipos de ticket &amp; origens (agora), e categorias, SLAs &amp; horário comercial (em breve) &mdash; coisas que realmente diferem de um cliente para o outro.',
            'settings_global_title' => 'Compartilhado entre todas as empresas',
            'settings_global_body' => 'Status e prioridades permanecem iguais em todos os lugares, para que os relatórios e os SLAs entre empresas fiquem consistentes; o mesmo vale para suas equipes, escala e caixas de entrada &mdash; sua própria operação, não a de um cliente.',
            'allview_heading' => '<strong>Um quadro único para todas as empresas</strong>',
            'allview_body' => 'O seletor de empresa no cabeçalho tem uma opção <strong>Todas as empresas</strong>. Todo ticket que você tem permissão para ver aparece em uma única lista, cada linha exibindo a empresa a que pertence &mdash; útil quando você atende várias entidades e quer uma visão única do dia sem perder de vista de quem é o quê.',
            'allview_card_scope_title' => 'Não concede nada novo',
            'allview_card_scope_body' => '"Todas" significa cada empresa que você já conseguia acessar uma de cada vez. Um analista que atende duas das suas três entidades vê exatamente essas duas, e um analista com uma empresa vê uma visão apenas daquela empresa.',
            'allview_card_props_title' => 'Cada entidade permanece separada',
            'allview_card_props_body' => 'Abra um ticket e o tipo, a origem, a categoria e a lista de resolução dele são os que pertencem <em>àquela</em> empresa &mdash; então uma categoria que uma entidade tem e outra não nunca pode ser aplicada ao ticket errado.',
            'allview_card_new_title' => 'Novos tickets perguntam qual empresa',
            'allview_card_new_body' => 'Não há uma única empresa ativa para presumir, e a escolha decide o número do ticket, a caixa postal de onde vêm as respostas e o SLA que se aplica. A lista de tipos é preenchida assim que você escolhe.',
            'allview_rule_chip' => 'Um ticket que chegou por e-mail ou pelo portal sem ainda ter sido roteado é marcado como <strong>Não roteado</strong> em vez de aparecer em Padrão, para que se destaque na triagem.',
            'allview_rule_reply' => 'As respostas ainda saem pela caixa postal em que o ticket chegou &mdash; isso segue o ticket, não a visualização, então um quadro combinado nunca envia pelo endereço errado.',
            'allview_rule_knowledge' => '<strong>Perguntar à IA</strong> pesquisa em todas as empresas que você pode ver enquanto a visualização combinada está ativa, em vez de apenas uma. Artigos compartilhados com todas as empresas são incluídos de qualquer forma.',
            'allview_rule_trash' => '<strong>Esvaziar a lixeira nunca abrange várias empresas.</strong> Sempre se aplica à única empresa que você escolheu por último, porque "excluir tudo na lixeira" em várias entidades de uma vez não é o que ninguém quer dizer com isso.',
            'allview_rule_other' => 'Só a lista de tickets se amplia. Ativos, mudanças, tarefas e o CMDB ainda mostram uma empresa de cada vez &mdash; troque para aquela empresa para trabalhar neles.',
            'privacy_heading' => 'Os tickets de cada empresa permanecem privados',
            'privacy_body' => 'Quando você está trabalhando no contexto de uma empresa, você só vê os tickets <strong>daquela</strong> empresa &mdash; na lista, na pesquisa, nos painéis e em cada ticket que você abre (incluindo seus e-mails, anexos, notas e histórico). Um membro da equipe só pode acessar um ticket se tiver recebido acesso à sua empresa (você escolhe as empresas de cada analista em Sistema &rarr; Analistas, ou concede a uma equipe inteira em Sistema &rarr; Equipes), então não há como se desviar para os dados de outro cliente. Essa separação é aplicada em todos os lugares nos bastidores, não apenas oculta da visão. Em uma instalação de empresa única, isso é automático e invisível &mdash; há apenas uma empresa, então tudo simplesmente pertence a ela.',
            'tip' => 'Em uma instalação de empresa única, nada disso aparece &mdash; há uma empresa, todo ticket pertence a ela, e não há seletor nem triagem. Esses recursos só são ativados quando uma segunda empresa existe.',
        ],
    ],
    'help_sla' => [
        'page_title' => 'Gestão de SLA',
        'back_link' => '&larr; Voltar ao guia de Tickets',
        'sidebar_title' => 'Guia de SLA',
        'hero_title' => 'Gerenciamento de SLA',
        'hero_sub' => 'Metas de resposta e resolução cientes do horário comercial, com notificações de violação por departamento',
        'nav' => [
            'overview' => 'Visão geral',
            'building_blocks' => 'Componentes básicos',
            'behaviour_settings' => 'Configurações de comportamento',
            'breach_notifications' => 'Notificações de violação',
            'cron_setup' => 'Configuração do cron',
            'worked_examples' => 'Exemplos práticos',
            'troubleshooting' => 'Solução de problemas',
        ],
        'overview' => [
            'heading' => 'Visão geral',
            'sub' => 'O que são SLAs, por que importam e como o mecanismo do FreeITSM funciona em alto nível.',
            'p1' => 'Um Acordo de Nível de Serviço (SLA) é uma promessa sobre a rapidez com que sua equipe responderá e resolverá um ticket. O FreeITSM acompanha dois cronômetros por ticket: <strong>resposta</strong> (tempo da criação do ticket até a primeira ação do analista) e <strong>resolução</strong> (tempo da criação do ticket até o encerramento do ticket). Ambas as metas são definidas por prioridade &mdash; então um P1 pode ter 30 minutos para resposta e 4 horas para resolução, enquanto um P4 pode ter 8 horas úteis e 5 dias úteis.',
            'switch_note' => 'Não usa SLAs? Desative o SLA em <strong>Sistema &rarr; Módulos &rarr; Disponibilidade &rarr; Recursos de tickets</strong>: relógios, avisos de violação e gatilhos de workflow de SLA param, enquanto os calendários comerciais permanecem para o horário de atendimento do chat web. Ao reativá-lo, pergunta se deve enviar os avisos perdidos enquanto esteve desativado ou ignorá-los.',
            'p2' => 'O mecanismo de SLA do FreeITSM tem quatro decisões de design que vale a pena entender:',
            'choice_business' => '<strong>Horário comercial, não o relógio de parede.</strong> Um P2 aberto às 16h30 com uma meta de resposta de 1 hora não viola às 17h30 se o escritório fecha às 17h. O cronômetro retoma às 9h do próximo dia útil. Este é o padrão do setor e o único modelo justo quando os analistas vão para casa à noite.',
            'choice_pause' => '<strong>Pausável.</strong> Quando um ticket está em um status marcado como "Pausar SLA" (como <em>Aguardando Resposta</em> ou <em>Em Espera</em>), o cronômetro para. Ele retoma quando o ticket volta a um status de trabalho.',
            'choice_compute' => '<strong>Calculado na leitura, não armazenado.</strong> O mecanismo recalcula o estado do SLA a partir do log de auditoria do ticket toda vez que você o consulta. Não há contadores armazenados que possam ficar fora de sincronia. Se você alterar o horário de um calendário comercial mais tarde, o SLA de cada ticket histórico é recalculado em relação ao novo horário na próxima vez que for visualizado.',
            'choice_cutoff' => '<strong>Corte de aplicação.</strong> Uma data "Aplicar SLAs a partir de" controlada pelo administrador significa que os tickets existentes no seu sistema não são repentinamente violados de forma retroativa quando você ativa os SLAs. Apenas os tickets criados na data de corte ou depois são acompanhados.',
            'tip' => 'Se você é novo na ITIL: o tempo de resposta é sobre reconhecimento (alguém o assumiu); o tempo de resolução é sobre conclusão (o problema do usuário foi corrigido). Os dois cronômetros correm de forma independente e têm metas diferentes.',
        ],
        'blocks' => [
            'heading' => 'Os quatro componentes básicos',
            'sub' => 'Configure estas quatro coisas e o acompanhamento de SLA estará operacional. Todo o resto é refinamento opcional.',
            'cal_heading' => '1. Calendários comerciais',
            'cal_intro' => 'Um calendário define quando sua central de serviços está aberta. Cada calendário tem:',
            'cal_tz' => '<strong>Fuso horário</strong> &mdash; um identificador de fuso horário IANA (ex. <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>). As transições de horário de verão são tratadas automaticamente.',
            'cal_hours' => '<strong>Horário de trabalho semanal</strong> &mdash; uma linha por dia da semana com uma caixa de seleção Aberto e horários de início / término. Os novos calendários têm o padrão Seg-Sex 09:00-17:00, Sáb/Dom fechado. Uma linha não marcada como Aberto significa que a central está fechada naquele dia.',
            'cal_holidays' => '<strong>Feriados</strong> &mdash; data + nome opcional. Os feriados anulam o padrão semanal (a central fica fechada mesmo que caia em uma segunda-feira).',
            'cal_default' => '<strong>Marcador de padrão</strong> &mdash; exatamente um calendário é o padrão. As novas prioridades o herdam, a menos que você especifique de outra forma.',
            'cal_outro' => 'Você pode criar quantos calendários precisar &mdash; um por escritório, um por equipe, um para clientes VIP com horário estendido. Eles são compartilhados pelas metas de SLA e pelo mecanismo de verificação de violação.',
            'prio_heading' => '2. Prioridades com metas de SLA',
            'prio_intro' => 'Na aba Prioridades (ou pela tabela de Metas de SLA na aba SLA), cada prioridade pode ter:',
            'prio_response' => '<strong>Meta de resposta (minutos)</strong> &mdash; quanto tempo até a primeira ação do analista.',
            'prio_resolution' => '<strong>Meta de resolução (minutos)</strong> &mdash; quanto tempo até o ticket ser fechado.',
            'prio_calendar' => '<strong>Calendário</strong> &mdash; em qual calendário comercial o cronômetro desta prioridade corre. Deixe em branco para usar o calendário padrão.',
            'prio_outro' => 'Deixar ambos os campos de meta em branco desativa completamente o acompanhamento de SLA para essa prioridade &mdash; útil para uma prioridade "Informativa" ou "Backlog" onde não há pressão de tempo.',
            'pause_heading' => '3. Status de pausa de SLA',
            'pause_intro' => 'Na aba Status há uma coluna dedicada "Pausar SLA". Marque qualquer status que represente o ticket bloqueado por algo fora do controle da equipe. Os candidatos padrão são:',
            'pause_awaiting' => '<strong>Aguardando Resposta</strong> &mdash; o cliente nos deve informações. Quase universalmente aceito como uma pausa justa.',
            'pause_vendor' => '<strong>Em Espera (Fornecedor)</strong> &mdash; aguardando o suporte da Microsoft / de terceiros.',
            'pause_change' => '<strong>Em Espera (Janela de Mudança)</strong> &mdash; agendado para uma futura janela de manutenção.',
            'pause_parts' => '<strong>Em Espera (Peças)</strong> &mdash; aguardando a entrega de hardware.',
            'pause_warn' => 'Um status genérico "Em Espera" pode ser abusado como válvula de escape de SLA quando um ticket é difícil ou o analista está ocupado. Se sua equipe tem disciplina, tudo bem. Se não, considere substituí-lo pelas variantes mais específicas acima, ou conte com o painel <strong>Watchtower</strong>, que sinaliza tickets pausados por mais de 24 horas como um alerta âmbar.',
            'cutoff_heading' => '4. Corte de aplicação (<code>Aplicar SLAs a partir de</code>)',
            'cutoff_p1' => 'A configuração global mais importante de todas. Até você definir uma data/hora aqui, o acompanhamento de SLA fica totalmente desativado &mdash; nenhum cronômetro corre, nenhuma pílula aparece na caixa de entrada, nenhum e-mail de violação é disparado. Defini-lo para uma data/hora passada ativa os SLAs retroativamente a partir daquele ponto. Defini-lo para uma data/hora futura agenda uma ativação.',
            'cutoff_p2' => 'A maioria das equipes define isso como "agora" quando habilita os SLAs pela primeira vez &mdash; os tickets existentes mantêm seu estado pré-SLA, os novos tickets a partir daquele momento são acompanhados.',
            'company_heading' => 'Cada cliente com suas próprias prioridades e horários',
            'company_p1' => 'Em uma instalação que atende várias empresas, uma prioridade ou um calendário comercial pode ser <strong>compartilhado</strong> por todas as empresas ou pertencer a <strong>uma empresa</strong> - escolha no campo <strong>Empresa</strong> ao adicioná-lo. Uma empresa vê suas próprias prioridades mais as compartilhadas que não ocultou, e inicia novos tickets no seu próprio padrão (senão no padrão compartilhado). Todo seletor de prioridade segue a empresa do ticket, e todo canal que abre um ticket o inicia no padrão dessa empresa.',
            'company_p2' => 'O relógio corre no calendário da própria prioridade; se ela não tem nenhum, no calendário padrão da empresa; depois no padrão compartilhado. Uma prioridade compartilhada só pode usar calendários compartilhados. Mover um ticket para uma empresa que não pode usar a prioridade dele o passa para o padrão dessa empresa, registrado no histórico do ticket.',
            'company_note' => 'Alterar uma prioridade ou calendário <strong>compartilhado</strong> o altera para todas as empresas, então exige acesso a todas as empresas. O de uma empresa exige acesso a essa empresa. Em uma instalação de uma só empresa, tudo isso é invisível - tudo é compartilhado.',
        ],
        'behaviour' => [
            'heading' => 'Configurações de comportamento',
            'sub' => 'Estas controlam como o mecanismo reage a casos extremos. Os padrões são sensatos &mdash; você só precisa revisá-los se tiver uma preferência específica.',
            'prio_heading' => 'Quando a prioridade muda no meio do caminho',
            'prio_intro' => 'Se um ticket P3 é elevado para P1 no meio do percurso (porque o problema acaba sendo maior do que se pensava), há três comportamentos razoáveis:',
            'prio_forward' => '<strong>Avançar (padrão)</strong> &mdash; preservar os minutos úteis acumulados e apenas redefinir a meta. Se o ticket havia usado 2h da sua meta P3 de 8h, ele agora tem 2h usadas contra sua meta P1 de 1h &mdash; o que significa que já está violado. Indiscutivelmente correto: o problema ERA um P1 o tempo todo, a equipe apenas não percebeu.',
            'prio_recompute' => '<strong>Recalcular</strong> &mdash; zerar o cronômetro e aplicar a nova meta retroativamente a partir da criação do ticket. Um recálculo limpo.',
            'prio_reset' => '<strong>Reiniciar</strong> &mdash; iniciar o novo cronômetro do zero a partir do momento da mudança de prioridade. O mais indulgente com a equipe, mas os clientes podem se sentir enganados se um ticket de alta prioridade de repente ganhar um novo cronômetro longo.',
            'reopen_heading' => 'Quando um ticket fechado é reaberto',
            'reopen_intro' => 'Se um ticket é reaberto (o usuário responde após o encerramento):',
            'reopen_reset' => '<strong>Reiniciar (padrão)</strong> &mdash; iniciar um novo cronômetro de resposta e resolução a partir do momento da reabertura. Trate a reabertura como efetivamente um novo ticket.',
            'reopen_continue' => '<strong>Continuar</strong> &mdash; retomar a partir do tempo decorrido no encerramento. As metas de SLA originais continuam a se aplicar.',
            'first_heading' => 'Definição de primeira resposta',
            'first_intro' => 'O que conta como "primeira resposta" &mdash; o momento que para o cronômetro de resposta?',
            'first_either' => '<strong>Qualquer (padrão)</strong> &mdash; a primeira ação do analista de qualquer tipo: um e-mail enviado, uma mudança de status, uma atribuição.',
            'first_status' => '<strong>Mudança de status</strong> &mdash; apenas uma mudança de status para fora do padrão conta. Mais rigoroso &mdash; o analista precisa ter realmente trabalhado no ticket, não apenas clicado nele.',
            'first_email' => '<strong>E-mail enviado</strong> &mdash; apenas uma resposta por e-mail ao solicitante conta. O mais rigoroso &mdash; o cliente precisa ter recebido notícias nossas.',
            'warn_heading' => 'Percentual do limiar de aviso',
            'warn_body' => 'Quão avançado na meta de SLA antes de o indicador mudar de verde para âmbar. O padrão é 80% &mdash; então uma meta de resposta de 60 minutos mostra âmbar aos 48 minutos decorridos. Também orienta as notificações de violação disparadas por aviso.',
        ],
        'breach' => [
            'heading' => 'Notificações de violação',
            'sub' => 'Regras de e-mail configuráveis por departamento que disparam quando os SLAs se aproximam da violação (aviso) ou realmente a violam.',
            'intro' => 'Cada regra tem quatro dimensões, todas independentes:',
            'scope_heading' => '1. Escopo',
            'scope_body' => 'Pode ser <strong>Padrão</strong> (a regra se aplica aos tickets de todos os departamentos) ou um <strong>departamento específico</strong>. Resolução: uma regra específica de departamento vence o padrão para os tickets daquele departamento. Sem uma regra padrão, os departamentos sem regra específica não recebem notificações.',
            'trigger_heading' => '2. Disparo',
            'trigger_body' => 'Pode ser <strong>Aviso</strong> (o ticket cruzou o limiar de aviso &mdash; possível violação) ou <strong>Violação</strong> (o ticket excedeu sua meta &mdash; violação real). Cada um é sua própria regra, então você pode notificar pessoas diferentes para cada um.',
            'target_heading' => '3. Alvo',
            'target_body' => 'Qual cronômetro observar &mdash; <strong>Resposta</strong>, <strong>Resolução</strong> ou <strong>Ambos</strong>.',
            'recip_heading' => '4. Destinatários',
            'recip_intro' => 'Qualquer combinação de:',
            'recip_assignee' => '<strong>O responsável pelo ticket</strong> &mdash; o analista que atualmente possui o ticket. Ignorado se não atribuído.',
            'recip_teams' => '<strong>Membros das equipes do departamento do ticket</strong> &mdash; todo analista em qualquer equipe vinculada ao departamento do ticket. Cobre a fila inteira sem manter uma lista de distribuição.',
            'recip_specific' => '<strong>Um analista específico</strong> &mdash; o padrão "campeão de SLA" / "gerente de serviço", em que é uma pessoa nomeada, não uma função.',
            'recip_custom' => '<strong>Endereços de e-mail personalizados</strong> &mdash; texto livre separado por vírgulas. Útil para caixas de entrada compartilhadas (<code>sla-alerts@empresa.com</code>), pontes de e-mail do Slack/Teams ou listas de distribuição.',
            'tip' => 'Cada ticket dispara no máximo um e-mail por (alvo, disparo) &mdash; o trabalhador do cron acompanha o que já foi enviado na tabela <code>sla_notifications_sent</code>. Então um aviso dispara uma vez, uma violação dispara uma vez, e é só isso &mdash; sem laços de spam.',
            'warn' => '<strong>Sem regras = sem e-mails.</strong> Mesmo que todos os tickets do sistema violem, nada dispara até você adicionar pelo menos uma regra. Comece com um par de Aviso + Violação de escopo Padrão para ter cobertura para tudo.',
        ],
        'cron' => [
            'heading' => 'Configurando o cron',
            'sub' => 'O script de verificação de violação precisa rodar em uma programação. Uma vez a cada 5 minutos é o ponto ideal.',
            'p1' => 'Os indicadores de SLA visíveis na interface (pílulas na caixa de entrada, painéis no painel de leitura) são calculados na hora quando uma página carrega. Mas os e-mails de violação só podem disparar se <em>algo</em> verificar proativamente os tickets mesmo quando ninguém está olhando para eles. Esse algo é uma tarefa agendada &mdash; no Windows, o Agendador de Tarefas; no Linux, o cron.',
            'p2' => 'O script é <code>cron/sla_breach_check.php</code> no diretório de instalação do FreeITSM. Ele pode ser invocado de duas formas:',
            'cli_heading' => 'A. CLI (recomendado em um servidor que você controla)',
            'cli_note' => 'Nenhuma autenticação necessária &mdash; as permissões do sistema de arquivos já controlam quem pode executá-lo.',
            'http_heading' => 'B. HTTP (para hospedagem compartilhada ou agendadores remotos)',
            'http_note' => 'O token é gerado automaticamente na primeira instalação e armazenado em <code>system_settings</code> sob a chave <code>sla_cron_token</code> (32 caracteres hexadecimais, ~128 bits de entropia). Encontre o seu com:',
            'win_heading' => 'Agendador de Tarefas do Windows',
            'win_intro' => 'Abra o Agendador de Tarefas (<code>taskschd.msc</code>) e crie uma nova tarefa com estas configurações:',
            'tbl_field' => 'Campo',
            'tbl_value' => 'Valor',
            'win_r1_k' => 'Nome',
            'win_r1_v' => 'FreeITSM &mdash; Verificação de Violação de SLA',
            'win_r2_k' => 'Executar estando o usuário conectado ou não',
            'win_r2_v' => 'Marque isto',
            'win_r3_k' => 'Disparador',
            'win_r3_v' => 'Diariamente, repetir a cada 1 dia, repetir a cada 5 minutos por 1 dia',
            'win_r4_k' => 'Ação',
            'win_r4_v' => 'Iniciar um programa',
            'win_r5_k' => 'Programa/script',
            'win_r5_v' => '<code>C:\\wamp64\\bin\\php\\php8.2.x\\php.exe</code>',
            'win_r6_k' => 'Adicionar argumentos',
            'win_r6_v' => '<code>C:\\wamp64\\www\\freeitsm-app\\cron\\sla_breach_check.php</code>',
            'win_r7_k' => 'Iniciar em',
            'win_r7_v' => '<code>C:\\wamp64\\www\\freeitsm-app</code>',
            'linux_heading' => 'Cron do Linux',
            'linux_intro' => 'Adicione uma linha ao seu crontab (<code>crontab -e</code>):',
            'sec_heading' => 'Segurança &mdash; o que protege o endpoint HTTP',
            'sec_intro' => 'Três camadas, todas aplicadas automaticamente:',
            'sec_token' => '<strong>1. Token de segredo compartilhado</strong> &mdash; aleatório de 128 bits por instalação, comparado com correspondência de tempo constante para evitar ataques de temporização.',
            'sec_lockout' => '<strong>2. Bloqueio de autenticação falha por IP</strong> &mdash; mais de 10 tentativas de token errado do mesmo IP na última hora dispara um bloqueio 429 de 1 hora. Frustra a sondagem por força bruta sem precisar de fail2ban.',
            'sec_interval' => '<strong>3. Intervalo mínimo entre execuções bem-sucedidas</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (padrão 30s). Mesmo uma requisição com token válido recebe um 429 se chegar mais cedo do que isso após a última execução bem-sucedida. Frustra o agendamento duplo acidental e os laços descontrolados.',
            'log_heading' => 'Registro de atividade',
            'log_body' => 'Toda invocação (aceita ou rejeitada) é registrada na tabela <code>sla_cron_runs</code> com tempo, resultado, contagens e IP do cliente. Veja as últimas 20 execuções no painel <strong>Atividade do Cron</strong> na parte inferior da aba de configurações de SLA &mdash; útil para verificar se a programação está disparando e para auditar quaisquer tentativas de autenticação falha. As linhas são removidas automaticamente após <code>sla_cron_log_retention_days</code> (padrão 30), para que a tabela permaneça pequena.',
        ],
        'examples' => [
            'heading' => 'Exemplos práticos',
            'sub' => 'Do caso simples de fuso horário único ao mais complicado entre fusos horários, onde "justo" precisa ser definido.',
            'ex1_heading' => 'Exemplo 1: Ticket aberto no Reino Unido, central de serviços no Reino Unido',
            'ex1_title' => 'O caso simples',
            'ex1_tag' => 'fuso horário único',
            'ex1_setup' => '<strong>Configuração:</strong> Um calendário comercial chamado <em>Escritório RU</em> com fuso horário <code>Europe/London</code>, Seg-Sex 09:00-17:00, sem feriados. A prioridade P2 tem uma meta de resposta de 1 hora e uma meta de resolução de 4 horas, ambas rodando contra o calendário <em>Escritório RU</em>.',
            'ex1_scenario' => '<strong>Cenário:</strong> O usuário abre um ticket P2 às <strong>16:30 RU na quarta-feira</strong>.',
            'ex1_timeline' => 'Qua 16:30 RU &mdash; <strong>ticket criado</strong>, cronômetro de resposta inicia.
Qua 17:00 RU &mdash; escritório fecha, cronômetro pausa (30 min consumidos de 60 min de meta).
Qui 09:00 RU &mdash; escritório abre, cronômetro retoma.
Qui 09:30 RU &mdash; analista responde. SLA de resposta cumprido bem no limite (60 min consumidos, 60 min de meta).',
            'ex1_outro' => 'Se o analista não tivesse respondido até <strong>quinta-feira 10:00 RU</strong>, a resposta teria <strong>violado por 30 minutos</strong> (90 min consumidos contra a meta de 60 min &mdash; 30 da quarta-feira à noite, 60 da quinta-feira de manhã). O cronômetro de 1 hora só corre durante o horário comercial, mas um ticket de fim de dia ainda consome a maior parte de seu orçamento durante a noite quando o escritório reabre &mdash; é fácil para um analista que chega às 09:00 supor que tem a hora inteira, quando na verdade restam apenas 30 minutos.',
            'ex2_heading' => 'Exemplo 2: Ticket aberto no Reino Unido, central de serviços na Estônia',
            'ex2_title' => 'O caso entre fusos horários',
            'ex2_tag' => '3 formas de definir "justo"',
            'ex2_setup' => '<strong>Configuração:</strong> Clientes do Reino Unido (<code>Europe/London</code>, GMT/BST), central de serviços na Estônia (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>2 horas à frente do RU</strong>). Ambas as centrais trabalham nominalmente das 09:00 às 17:00 no horário local.',
            'ex2_scenario' => '<strong>Cenário:</strong> O cliente do RU abre um ticket P2 às <strong>16:30 RU na sexta-feira</strong> (= 18:30 na Estônia, após o fechamento na Estônia). A próxima oportunidade de um analista da Estônia trabalhá-lo é segunda-feira às 09:00 na Estônia (= 07:00 RU). A meta de resposta é de 1 hora.',
            'ex2_question' => 'O que o SLA deveria dizer? Há três respostas defensáveis, cada uma justa em um sentido diferente. Você escolhe qual calendário atribuir à prioridade com base no que seu contrato de serviço promete.',
            'optA_label' => 'Opção A &mdash; Centrada no cliente',
            'optA_p1' => '<strong>Defina a prioridade para usar um calendário com horário do <em>RU</em>.</strong> O cronômetro corre contra o RU 09:00-17:00, independentemente de onde o analista esteja.',
            'optA_p2' => 'No cenário acima, ticket aberto às 16:30 RU sexta-feira: o cronômetro corre 16:30&ndash;17:00 RU sexta (30 min consumidos), pausa durante a noite + fim de semana, retoma seg 09:00 RU. Se um analista da Estônia responder às 10:00 na Estônia segunda (= 08:00 RU), o calendário do RU ainda está pausado (o escritório do RU abre às 09:00 RU), então nenhum minuto adicional corre &mdash; o consumo permanece em 30 min. <strong>SLA cumprido com 30 min de margem</strong>. Qualquer resposta após as 09:30 RU (= 11:30 na Estônia) violaria.',
            'optA_p3' => '<em>Justo para:</em> o cliente. A experiência dele corresponde ao seu dia de trabalho.<br><em>Compensação:</em> Espera-se que os analistas da Estônia estejam disponíveis das 09:00 às 17:00 no horário do RU (= 11:00-19:00 na Estônia), o que estende o dia de trabalho deles em 2 horas.',
            'optB_label' => 'Opção B &mdash; Centrada no analista',
            'optB_p1' => '<strong>Defina a prioridade para usar um calendário com horário da <em>Estônia</em>.</strong> O cronômetro corre contra a Estônia 09:00-17:00.',
            'optB_p2' => 'Mesmo cenário: ticket aberto às 18:30 na Estônia sexta (após o fechamento), cronômetro pausado todo o fim de semana, começa a correr seg 09:00 na Estônia (= 07:00 RU). Se o analista responder às 09:30 na Estônia segunda (= 07:30 RU), o SLA de resposta consumiu 30 min da meta de 60 min &mdash; <strong>cumprido com 30 min de margem</strong>. O cliente do RU abriu às 16:30 RU sexta e recebeu uma resposta às 07:30 RU segunda &mdash; a espera no relógio de parede foi muito maior do que o SLA sugere.',
            'optB_p3' => '<em>Justo para:</em> os analistas. Eles trabalham no horário normal.<br><em>Compensação:</em> Os clientes do RU podem sentir que o SLA está "mentindo" se um ticket de sexta à tarde não for reconhecido até segunda de manhã no horário da Estônia, mas o relatório diz que o SLA de resposta foi de 1 hora. Certifique-se de que seu contrato de serviço seja explícito de que o SLA corre contra o horário da central de suporte.',
            'optC_label' => 'Opção C &mdash; Janela de sobreposição (o mais rigoroso)',
            'optC_p1' => '<strong>Defina a prioridade para usar um calendário cobrindo apenas as horas em que ambas as centrais estão abertas.</strong> O RU 09:00-17:00 se sobrepõe à Estônia 09:00-17:00 (= RU 07:00-15:00) durante a <strong>janela RU 09:00-15:00</strong> &mdash; 6 horas por dia útil.',
            'optC_p2' => 'Mesmo cenário: ticket aberto às 16:30 RU sexta (fora da sobreposição, já que a sobreposição fecha às 15:00 RU), cronômetro pausado durante o fim de semana, retoma seg 09:00 RU (= 11:00 na Estônia, o momento em que a sobreposição reabre). Se o analista da Estônia responder às 11:30 na Estônia (= 09:30 RU), o SLA de resposta consumiu 30 min da meta de 60 min &mdash; <strong>cumprido com 30 min de margem</strong>. A resposta aconteceu durante a janela de sobreposição, então conta imediatamente.',
            'optC_p3' => '<em>Justo para:</em> ambos os lados &mdash; o SLA só corre durante as horas em que a central poderia realmente avançar o ticket E o cliente está em sua mesa para receber uma resposta.<br><em>Compensação:</em> Uma janela diária mais curta significa tempos de relógio de parede maiores para cumprir metas agressivas. Uma meta de resolução de 4 horas abrange 1,5 dia de sobreposição, enquanto com um calendário normal de 8 horas estaria pronta dentro de um único dia.',
            'choose_tip' => '<strong>Como escolher:</strong> Veja seu contrato de serviço. Se ele diz "resposta em até 1 hora do recebimento" &mdash; isso é a Opção A (o relógio do cliente). Se diz "resposta em até 1 hora útil" &mdash; isso é tipicamente a Opção B (qualquer que seja a central que esteja trabalhando). Se diz "em até 1 hora de disponibilidade mútua" &mdash; isso é a Opção C. Se não houver contrato, pergunte à equipe: vocês querem sentir pressão fora do horário da Estônia (Opção A) ou querem que os clientes do RU ocasionalmente se sintam ignorados (Opção B)?',
            'ex3_heading' => 'Exemplo 3: Pausar o cronômetro durante uma espera por fornecedor',
            'ex3_title' => 'Como os status de pausa funcionam na prática',
            'ex3_tag' => 'pausar o cronômetro',
            'ex3_setup' => '<strong>Configuração:</strong> Prioridade P3 com meta de resolução de 8 horas úteis, calendário do RU, status "Aguardando Fornecedor" marcado como <em>Pausar SLA</em>.',
            'ex3_scenario' => '<strong>Cenário:</strong> Ticket aberto seg 09:00 RU. O analista escala para a Microsoft seg 11:00 RU e move o ticket para "Aguardando Fornecedor". A Microsoft responde qua 14:00 RU. O analista implementa a correção e fecha qui 10:00 RU.',
            'ex3_timeline' => 'Seg 09:00 &mdash; ticket criado, cronômetro de resolução correndo.
Seg 11:00 &mdash; movido para "Aguardando Fornecedor", <strong>cronômetro pausado</strong> (2h consumidas).
Qua 14:00 &mdash; movido de volta para "Em Andamento", <strong>cronômetro retoma</strong>.
Qua 17:00 &mdash; escritório fecha (5h consumidas no total).
Qui 09:00 &mdash; escritório abre.
Qui 10:00 &mdash; ticket fechado (6h consumidas no total). <strong>SLA cumprido</strong> contra a meta de 8h.',
            'ex3_outro' => 'Tempo decorrido no relógio de parede: ~3 dias. Tempo decorrido de SLA: 6 horas úteis. Sem o marcador de status de pausa, o SLA teria contado todos os 2 dias de espera por fornecedor + horário comercial, totalizando ~18 horas úteis &mdash; bem acima da violação.',
        ],
        'trouble' => [
            'heading' => 'Solução de problemas',
            'sub' => 'Problemas comuns e o que verificar.',
            'col_symptom' => 'Sintoma',
            'col_cause' => 'Causa provável',
            'r1_s' => 'Nenhuma pílula de SLA aparece na caixa de entrada',
            'r1_c' => '<code>Aplicar SLAs a partir de</code> está em branco, a prioridade não tem metas definidas, ou o ticket é anterior ao corte.',
